/* DAWAH X — ahmad, অধ্যায় 72 · খণ্ড 72 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][72]=[[14201,14201,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَفْضَلُ ‏ ‏الصَّدَقَةِ ‏ ‏صَدَقَةٌ ‏ ‏عَنْ ‏ ‏ظَهْرِ غِنًى ‏ ‏وَابْدَأْ بِمَنْ ‏ ‏تَعُولُ ‏ ‏وَالْيَدُ الْعُلْيَا خَيْرٌ مِنْ الْيَدِ السُّفْلَى ‏","","",""],[14202,14202,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ ‏ ‏جَابِرًا ‏ ‏أَسَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِذَا دَخَلَ الرَّجُلُ بَيْتَهُ يُسَلِّمُ وَالْمُؤْمِنُ يَأْكُلُ فِي مِعًى وَاحِدٍ قَالَ نَعَمْ قَالَ وَسَأَلْتُ ‏ ‏جَابِرًا ‏ ‏أَسَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا دَخَلَ الرَّجُلُ بَيْتَهُ فَذَكَرَ اسْمَ اللَّهِ حِينَ يَدْخُلُ وَحِينَ يَطْعَمُ قَالَ الشَّيْطَانُ لَا مَبِيتَ لَكُمْ وَلَا عَشَاءَ هَاهُنَا وَإِنْ دَخَلَ فَلَمْ يَذْكُرْ اسْمَ اللَّهِ عِنْدَ دُخُولِهِ قَالَ أَدْرَكْتُمْ الْمَبِيتَ وَإِنْ لَمْ يَذْكُرْ اسْمَ اللَّهِ عِنْدَ مَطْعَمِهِ قَالَ أَدْرَكْتُمْ الْمَبِيتَ وَالْعَشَاءَ قَالَ نَعَمْ ‏","","",""],[14203,14203,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ ‏ ‏جَابِرًا ‏ ‏عَنْ خَادِمِ الرَّجُلِ إِذَا كَفَاهُ الْمَشَقَّةَ وَالْحَرَّ فَقَالَ ‏ ‏أَمَرَنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نَدْعُوَهُ فَإِنْ كَرِهَ أَحَدٌ أَنْ يَطْعَمَ مَعَهُ فَلْيُطْعِمْهُ أُكْلَةً فِي يَدِهِ ‏","","",""],[14204,14204,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏أَسَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَزْنِي الزَّانِي حِينَ يَزْنِي وَهُوَ مُؤْمِنٌ وَلَا يَسْرِقُ حِينَ يَسْرِقُ وَهُوَ مُؤْمِنٌ قَالَ ‏ ‏جَابِرٌ ‏ ‏لَمْ أَسْمَعْهُ قَالَ ‏ ‏جَابِرٌ ‏ ‏وَأَخْبَرَنِي ‏ ‏ابْنُ عَمْرٍو ‏ ‏أَنَّهُ قَدْ سَمِعَهُ ‏","","",""],[14205,14205,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏جَابِرًا ‏ ‏أخْبَرَهُ ‏ ‏أَنَّهُمْ غَزَوْا غَزْوَةً بَيْنَ ‏ ‏مَكَّةَ ‏ ‏وَالْمَدِينَةِ ‏ ‏فَهَاجَتْ عَلَيْهِمْ رِيحٌ شَدِيدَةٌ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهَا لِمَوْتِ ‏ ‏مُنَافِقٍ ‏ ‏فَرَجَعْنَا إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَوَجَدْنَا ‏ ‏مُنَافِقًا ‏ ‏عَظِيمَ النِّفَاقِ قَدْ مَاتَ ‏","","",""],[14206,14206,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا فُتِحَتْ ‏ ‏حُنَيْنٌ ‏ ‏بَعَثَ ‏ ‏سَرَايَا ‏ ‏فَأَتَوْا بِالْإِبِلِ وَالشَّاءِ ‏ ‏فَقَسَمَهَا ‏ ‏فِي ‏ ‏قُرَيْشٍ ‏ ‏قَالَ فَوَجَدْنَا أَيُّهَا ‏ ‏الْأَنْصَارُ ‏ ‏عَلَيْهِ فَبَلَغَهُ ذَلِكَ فَجَمَعَنَا فَخَطَبَنَا فَقَالَ ‏ ‏أَلَا تَرْضَوْنَ أَنَّكُمْ ‏ ‏أُعْطِيتُمْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَاللَّهِ لَوْ سَلَكَتْ النَّاسُ وَادِيًا وَسَلَكْتُمْ شِعْبًا لَاتَّبَعْتُ شِعْبَكُمْ قَالُوا رَضِينَا يَا رَسُولَ اللَّهِ ‏","","",""],[14207,14207,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ ‏ ‏الْعَقَبَةِ ‏ ‏قَالَ شَهِدَهَا سَبْعُونَ فَوَافَقَهُمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَبَّاسُ بْنُ عَبْدِ الْمُطَّلِبِ ‏ ‏آخِذٌ بِيَدِهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ أَخَذْتُ وَأَعْطَيْتُ ‏","","",""],[14208,14208,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ أَخْبَرَهُ أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏أَخْبَرَهُ أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏سَيَخْرُجُ أَهْلُ ‏ ‏مَكَّةَ ‏ ‏مِنْهَا ثُمَّ لَا يَعْمُرُوهَا ‏ ‏أَوْ لَا تُعْمَرُ ‏ ‏إِلَّا قَلِيلًا ثُمَّ تُعْمَرُ وَتَمْتَلِئُ ‏ ‏وَتُبْنَى ثُمَّ يَخْرُجُونَ مِنْهَا فَلَا يَعُودُونَ إِلَيْهَا أَبَدًا ‏","","",""],[14209,14209,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏وَقُتَيْبَةُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيَسِيرَنَّ رَاكِبٌ فِي جِهَةِ ‏ ‏الْمَدِينَةِ ‏ ‏قَالَ ‏ ‏قُتَيْبَةُ ‏ ‏فِي جَانِبِ ‏ ‏الْمَدِينَةِ ‏ ‏فَيَقُولَنَّ لَقَدْ كَانَ فِي هَذِهِ مَرَّةً حَاضِرٌ مِنْ الْمُؤْمِنِينَ كَثِيرٌ ‏","","",""],[14210,14210,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏جَابِرًا ‏ ‏أَخْبَرَهُ أَنَّهُ قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَحِلُّ لِأَحَدٍ يَحْمِلُ فِيهَا السِّلَاحَ لِقِتَالٍ ‏ ‏فَقَالَ ‏ ‏قُتَيْبَةُ ‏ ‏يَعْنِي ‏ ‏الْمَدِينَةَ ‏","","",""],[14211,14211,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَهْدَى إِلَيْهِ رَاهِبٌ مِنْ ‏ ‏الشَّامِ ‏ ‏جُبَّةً ‏ ‏مِنْ ‏ ‏سُنْدُسٍ ‏ ‏فَلَبِسَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ أَتَى الْبَيْتَ فَوَضَعَهَا وَأُخْبِرَ بِوَفْدٍ يَأْتِيهِ فَأَمَرَهُ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏أَنْ يَلْبَسَ ‏ ‏الْجُبَّةَ ‏ ‏لِقُدُومِ الْوَفْدِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَصْلُحُ لَنَا لِبَاسُهَا فِي الدُّنْيَا وَيَصْلُحُ لَنَا لِبَاسُهَا فِي الْآخِرَةِ وَلَكِنْ خُذْهَا يَا ‏ ‏عُمَرُ ‏ ‏فَقَالَ أَتَكْرَهُهَا وَآخُذُهَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَا آمُرُكَ أَنْ تَلْبَسَهَا وَلَكِنْ تُرْسِلُ بِهَا إِلَى أَرْضِ ‏ ‏فَارِسَ ‏ ‏فَتُصِيبُ بِهَا مَالًا فَأَبَى ‏ ‏عُمَرُ ‏ ‏فَأَرْسَلَ بِهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏النَّجَاشِيِّ ‏ ‏وَكَانَ قَدْ أَحْسَنَ إِلَى مَنْ ‏ ‏فَرَّ ‏ ‏إِلَيْهِ مِنْ ‏ ‏أَصْحَابِ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[14212,14212,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏وَحَسَنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏وَقَالَ ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ ‏ ‏جَابِرًا ‏ ‏عَنْ ‏ ‏مِيثَرَةٍ ‏ ‏قَالَ ‏ ‏الْأُرْجُوَانِ ‏ ‏فَقَالَ ‏ ‏جَابِرٌ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا أَرْكَبُهَا وَلَا أَلْبَسُ قَمِيصًا مَكْفُوفًا بِحَرِيرٍ وَلَا أَلْبَسُ ‏ ‏الْقَسِّيَّ ‏","","",""],[14213,14213,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنِ ‏ ‏الْبَهْزِيَّةِ أُمِّ مَالِكٍ ‏ ‏كَانَتْ ‏ ‏تُهْدِي فِي ‏ ‏عُكَّةٍ ‏ ‏لَهَا سَمْنًا لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبَيْنَمَا بَنُوهَا يَسْأَلُونَهَا عَنْ ‏ ‏إِدَامٍ ‏ ‏وَلَيْسَ عِنْدَهَا شَيْءٌ ‏ ‏فَعَمَدَتْ إِلَى ‏ ‏نِحْيِهَا الَّتِي كَانَتْ ‏ ‏تُهْدِي فِيهِ السَّمْنَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَجَدَتْ فِيهِ سَمْنًا فَمَا زَالَ يُقِيمُ لَهَا ‏ ‏إِدَامَ ‏ ‏بَنِيهَا حَتَّى عَصَرَتْهُ فَأَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَعَصَرْتِيهِ فَقَالَتْ نَعَمْ قَالَ لَوْ ‏ ‏تَرَكْتِيهِ مَا زَالَ ذَلِكَ مُقِيمًا ‏","","",""],[14214,14214,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ أَتَاهُ رَجُلٌ يَسْتَطْعِمُهُ ‏ ‏فَأَطْعَمَهُ ‏ ‏شَطْرَ ‏ ‏وَسْقِ ‏ ‏شَعِيرٍ فَمَا زَالَ الرَّجُلُ يَأْكُلُ مِنْهُ هُوَ وَامْرَأَتُهُ وَوَصِيفٌ لَهُمْ حَتَّى كَالُوهُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ لَمْ تَكِيلُوهُ لَأَكَلْتُمْ مِنْهُ وَلَقَامَ لَكُمْ ‏","","",""],[14215,14215,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ ‏ ‏بَنَّةَ الْجُهَنِيَّ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ عَلَى قَوْمٍ فِي الْمَسْجِدِ ‏ ‏أَوْ فِي الْمَجْلِسِ ‏ ‏يَسُلُّونَ سَيْفًا بَيْنَهُمْ يَتَعَاطَوْنَهُ بَيْنَهُمْ غَيْرَ مَغْمُودٍ فَقَالَ ‏ ‏لَعَنَ اللَّهُ مَنْ يَفْعَلُ ذَلِكَ ‏ ‏أَوَ لَمْ أَزْجُرْكُمْ عَنْ هَذَا فَإِذَا سَلَلْتُمْ السَّيْفَ فَلْيَغْمِدْهُ الرَّجُلُ ثُمَّ لِيُعْطِهِ كَذَلِكَ ‏","","",""],[14216,14216,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏وَحَسَنٌ ‏ ‏وَاللَّفْظُ لَفْظُ ‏ ‏حَسَنٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏هَلْ سَمِعْتَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ الرَّجُلُ فِي صَلَاةٍ مَا انْتَظَرَ الصَّلَاةَ قَالَ انْتَظَرْنَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةً لِصَلَاةِ الْعَتَمَةِ فَاحْتَبَسَ عَلَيْنَا حَتَّى كَانَ قَرِيبًا مِنْ شَطْرِ اللَّيْلِ ‏ ‏أَوْ بَلَغَ ذَلِكَ ‏ ‏ثُمَّ جَاءَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّيْنَا ثُمَّ قَالَ اجْلِسُوا فَخَطَبَنَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ النَّاسَ قَدْ صَلَّوْا وَرَقَدُوا وَأَنْتُمْ لَمْ تَزَالُوا فِي صَلَاةٍ مَا انْتَظَرْتُمْ الصَّلَاةَ ‏","","",""],[14217,14217,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏جَابِرٌ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا أَحَدُكُمْ أَعْجَبَتْهُ الْمَرْأَةُ فَوَقَعَتْ فِي نَفْسِهِ فَلْيَعْمِدْ إِلَى امْرَأَتِهِ فَلْيُوَاقِعْهَا فَإِنَّ ذَلِكَ يَرُدُّ مِنْ نَفْسِهِ ‏","","",""],[14218,14218,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ الرَّجُلِ ‏ ‏يُوتِرُ ‏ ‏عِشَاءً ثُمَّ يَرْقُدُ قَالَ ‏ ‏جَابِرٌ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ خَافَ مِنْكُمْ أَنْ لَا يَقُومَ مِنْ اللَّيْلِ ‏ ‏فَلْيُوتِرْ ‏ ‏ثُمَّ لِيَرْقُدْ وَمَنْ طَمِعَ مِنْكُمْ الْقِيَامَ ‏ ‏فَلْيُوتِرْ ‏ ‏مِنْ آخِرِ اللَّيْلِ فَإِنَّ قِرَاءَةَ آخِرِ اللَّيْلِ مَحْضُورَةٌ وَذَلِكَ أَفْضَلُ ‏","","",""],[14219,14219,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مِنْ اللَّيْلِ سَاعَةً لَا يُوَافِقُهَا عَبْدٌ مُسْلِمٌ يَسْأَلُ اللَّهَ خَيْرًا إِلَّا أَعْطَاهُ وَهِيَ كُلَّ لَيْلَةٍ ‏","","",""],[14220,14220,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ ‏ ‏نُعْمَانَ بْنَ قَوْقَلٍ ‏ ‏جَاءَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏أَرَأَيْتَ إِذَا صَلَّيْتُ ‏ ‏الْمَكْتُوبَاتِ ‏ ‏وَصُمْتُ رَمَضَانَ وَحَرَّمْتُ الْحَرَامَ وَأَحْلَلْتُ الْحَلَالَ وَلَمْ أَزِدْ عَلَى ذَلِكَ شَيْئًا أَفَأَدْخُلُ الْجَنَّةَ قَالَ نَعَمْ فَقَالَ وَاللَّهِ لَا أَزِيدُ عَلَى ذَلِكَ شَيْئًا ‏","","",""],[14221,14221,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏أَشَدَّ النَّاسِ تَخْفِيفًا فِي الصَّلَاةِ ‏","","",""],[14222,14222,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏أَنَّهُ قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏هَلْ جَمَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ قَالَ نَعَمْ زَمَانَ غَزْوِنَا ‏ ‏بَنِي الْمُصْطَلِقِ ‏","","",""],[14223,14223,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ ‏ ‏جَابِرًا ‏ ‏عَنْ التَّصْفِيقِ وَالتَّسْبِيحِ ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏التَّصْفِيقُ لِلنِّسَاءِ فِي الصَّلَاةِ وَالتَّسْبِيحُ لِلرِّجَالِ ‏","","",""],[14224,14224,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏غَزَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سِتَّ مِرَارٍ قَبْلَ صَلَاةِ الْخَوْفِ وَكَانَتْ صَلَاةُ الْخَوْفِ فِي السَّنَةِ السَّابِعَةِ ‏","","",""],[14225,14225,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ الْغُسْلِ قَالَ ‏ ‏جَابِرٌ ‏ ‏أَتَتْ ‏ ‏ثَقِيفٌ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ إِنَّ أَرْضَنَا أَرْضٌ بَارِدَةٌ فَكَيْفَ تَأْمُرُنَا بِالْغُسْلِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّا ‏ ‏أَنَا فَأَصُبُّ عَلَى رَأْسِي ثَلَاثَ مَرَّاتٍ وَلَمْ يَقُلْ غَيْرَ ذَلِكَ ‏","","",""],[14226,14226,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ الرَّجُلِ ‏ ‏يُبَاشِرُ ‏ ‏الرَّجُلَ ‏ ‏فَقَالَ ‏ ‏جَابِرٌ ‏ ‏زَجَرَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ ‏","","",""],[14227,14227,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ الْمَرْأَةِ تُبَاشِرُ الْمَرْأَةَ قَالَ زَجَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ ‏","","",""],[14228,14228,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ الرَّجُلِ يُرِيدُ الصِّيَامَ وَالْإِنَاءُ عَلَى يَدِهِ لِيَشْرَبَ مِنْهُ فَيَسْمَعُ النِّدَاءَ ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏كُنَّا نُحَدَّثُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِيَشْرَبْ ‏","","",""],[14229,14229,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَطْلُعُ الشَّمْسُ فِي قَرْنِ شَيْطَانٍ ‏","","",""],[14230,14230,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ رُكُوبِ الْهَدْيِ قَالَ ‏ ‏جَابِرٌ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏ارْكَبْهَا بِالْمَعْرُوفِ حَتَّى تَجِدَ ظَهْرًا ‏","","",""],[14231,14231,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَوْمِ عَاشُورَاءَ ‏ ‏أَنْ نَصُومَهُ ‏","","",""],[14232,14232,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏وَحَسَنُ بْنُ مُوسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ النَّحْرِ فَقَالَ ‏ ‏جَابِرٌ ‏ ‏صَلَّى بِنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ النَّحْرِ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَتَقَدَّمَ رِجَالٌ فَنَحَرُوا وَظَنُّوا أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ نَحَرَ فَأَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَ نَحَرَ أَنْ يُعِيدَ نَحْرًا آخَرَ وَلَا يَنْحَرُوا حَتَّى يَنْحَرَ ‏","","",""],[14233,14233,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ الرَّجُلِ ‏ ‏يُوَالِي ‏ ‏مَوَالِيَ ‏ ‏الرَّجُلِ بِغَيْرِ إِذْنِهِ فَقَالَ كَتَبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى كُلِّ بَطْنٍ عُقُولَهُمْ ثُمَّ كَتَبَ أَنَّهُ لَا يَحِلُّ أَنْ ‏ ‏يُوَالِيَ ‏ ‏مَوَالِيَ ‏ ‏رَجُلٍ بِغَيْرِ إِذْنِهِ ‏","","",""],[14234,14234,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏وَحَسَنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلُ الْمُؤْمِنِ كَمَثَلِ السُّنْبُلَةِ تَخِرُّ مَرَّةً وَتَسْتَقِيمُ مَرَّةً وَمَثَلُ الْكَافِرِ مَثَلُ الْأَرْزِ لَا يَزَالُ مُسْتَقِيمًا حَتَّى يَخِرَّ وَلَا يَشْعُرَ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏الْأَرْزَةِ ‏","","",""],[14235,14235,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ خُسُوفِ الشَّمْسِ وَالْقَمَرِ ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الشَّمْسَ وَالْقَمَرَ إِذَا خُسِفَا أَوْ أَحَدُهُمَا فَإِذَا رَأَيْتُمْ ذَلِكَ فَصَلُّوا حَتَّى ‏ ‏يَنْجَلِيَ ‏ ‏خُسُوفُ أَيِّهِمَا خُسِفَ ‏","","",""],[14236,14236,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ الْقَتِيلِ الَّذِي قُتِلَ فَأَذَّنَ فِيهِ ‏ ‏سُحَيْمٌ ‏ ‏فَقَالَ ‏ ‏جَابِرٌ ‏ ‏أَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُحَيْمًا ‏ ‏أَنْ يُؤَذِّنَ فِي النَّاسِ أَلَا لَا يَدْخُلُ الْجَنَّةَ إِلَّا مُؤْمِنٌ ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏وَلَا أَعْلَمُهُ قُتِلَ أَحَدٌ ‏","","",""],[14237,14237,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ الْقَتِيلِ الَّذِي قُتِلَ فَأَذَّنَ فِيهِ ‏ ‏سُحَيْمٌ ‏ ‏قَالَ كُنَّا ‏ ‏بِحُنَيْنٍ ‏ ‏فَأَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُحَيْمًا ‏ ‏أَنْ يُؤَذِّنَ فِي النَّاسِ أَنْ لَا يَدْخُلَ الْجَنَّةَ إِلَّا مُؤْمِنٌ ‏ ‏قَالَ ‏ ‏وَلَا أَعْلَمُهُ قُتِلَ أَحَدٌ ‏ ‏قَالَ ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَتَلَ أَحَدًا ‏","","",""],[14238,14238,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏أَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الطِّيَرَةِ وَالْعَدْوَى شَيْئًا ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏سَمِعْتُهُ يَقُولُ ‏ ‏كُلُّ عَبْدٍ طَائِرُهُ فِي عُنُقِهِ ‏","","",""],[14239,14239,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَفَّنَ أَحَدُكُمْ أَخَاهُ فَلْيُحْسِنْ كَفَنَهُ وَصَلُّوا عَلَى الْمَيِّتِ أَرْبَعَ تَكْبِيرَاتٍ فِي اللَّيْلِ وَالنَّهَارِ سَوَاءً ‏","","",""],[14240,14240,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ثَمَنِ السِّنَّوْرِ وَهُوَ الْقِطُّ ‏","","",""],[14241,14241,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏وَجَنَازَةُ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏بَيْنَ أَيْدِيهِمْ اهْتَزَّ لَهَا عَرْشُ الرَّحْمَنِ ‏","","",""],[14242,14242,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَأْكُلُ أَهْلُ الْجَنَّةِ فِيهَا وَيَشْرَبُونَ وَلَا يَمْتَخِطُونَ وَلَا يَتَغَوَّطُونَ وَلَا يَبُولُونَ إِنَّمَا طَعَامُهُمْ ‏ ‏جُشَاءٌ ‏ ‏رَشْحٌ ‏ ‏كَرَشْحِ ‏ ‏الْمِسْكِ ‏ ‏فَيُلْهَمُونَ التَّسْبِيحَ وَالتَّحْمِيدَ كَمَا يُلْهَمُونَ النَّفَسَ ‏","","",""],[14243,14243,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ ‏ ‏اشْتِمَالِ ‏ ‏الصَّمَّاءِ ‏ ‏وَالِاحْتِبَاءِ ‏ ‏فِي ثَوْبٍ وَاحِدٍ وَأَنْ يَرْفَعَ الرَّجُلُ إِحْدَى رِجْلَيْهِ عَلَى الْأُخْرَى وَهُوَ مُسْتَلْقٍ عَلَى ظَهْرِهِ ‏","","",""],[14244,14244,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عَبْدًا ‏ ‏لِحَاطِبٍ ‏ ‏جَاءَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَشْتَكِي ‏ ‏حَاطِبًا ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ لَيَدْخُلَنَّ ‏ ‏حَاطِبٌ ‏ ‏النَّارَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَذَبْتَ لَا يَدْخُلُهَا فَإِنَّهُ شَهِدَ ‏ ‏بَدْرًا ‏ ‏وَالْحُدَيْبِيَةَ ‏","","",""],[14245,14245,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏وَإِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏جَاءَ عَبْدٌ فَبَايَعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْهِجْرَةِ وَلَمْ ‏ ‏يَشْعُرْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ عَبْدٌ فَجَاءَ سَيِّدُهُ يُرِيدُهُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعْنِيهِ فَاشْتَرَاهُ بِعَبْدَيْنِ أَسْوَدَيْنِ ثُمَّ لَمْ يُبَايِعْ أَحَدًا بَعْدُ حَتَّى يَسْأَلَهُ أَعَبْدٌ هُوَ ‏","","",""],[14246,14246,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ ‏ ‏قَالَ ‏ ‏رُمِيَ يَوْمَ الْأَحْزَابِ ‏ ‏سَعْدُ بْنُ مُعَاذٍ ‏ ‏فَقَطَعُوا ‏ ‏أَكْحَلَهُ ‏ ‏فَحَسَمَهُ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالنَّارِ فَانْتَفَخَتْ يَدُهُ ‏ ‏فَحَسَمَهُ ‏ ‏فَانْتَفَخَتْ يَدُهُ ‏ ‏فَحَسَمَهُ ‏ ‏أُخْرَى فَانْتَفَخَتْ يَدُهُ فَنَزَفَهُ فَلَمَّا رَأَى ذَلِكَ قَالَ ‏ ‏اللَّهُمَّ لَا تُخْرِجْ نَفْسِي حَتَّى تُقِرَّ عَيْنِي مِنْ ‏ ‏بَنِي قُرَيْظَةَ ‏ ‏فَاسْتَمْسَكَ ‏ ‏عِرْقُهُ فَمَا قَطَرَ قَطْرَةً حَتَّى نَزَلُوا عَلَى حُكْمِ ‏ ‏سَعْدٍ ‏ ‏فَأُرْسِلَ إِلَيْهِ فَحَكَمَ أَنْ تُقْتَلَ رِجَالُهُمْ ‏ ‏وَيُسْتَحْيَا نِسَاؤُهُمْ ‏ ‏وَذَرَارِيُّهُمْ ‏ ‏لِيَسْتَعِينَ بِهِمْ الْمُسْلِمُونَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَصَبْتَ حُكْمَ اللَّهِ فِيهِمْ وَكَانُوا أَرْبَعَ مِائَةٍ فَلَمَّا فُرِغَ مِنْ قَتْلِهِمْ ‏ ‏انْفَتَقَ ‏ ‏عِرْقُهُ فَمَاتَ ‏","","",""],[14247,14247,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏حَاطِبَ بْنَ أَبِي بَلْتَعَةَ ‏ ‏كَتَبَ إِلَى أَهْلِ ‏ ‏مَكَّةَ ‏ ‏يَذْكُرُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرَادَ غَزْوَهُمْ فَدُلَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمَرْأَةِ الَّتِي مَعَهَا الْكِتَابُ فَأَرْسَلَ إِلَيْهَا فَأُخِذَ كِتَابُهَا مِنْ رَأْسِهَا وَقَالَ يَا ‏ ‏حَاطِبُ ‏ ‏أَفَعَلْتَ قَالَ نَعَمْ أَمَا إِنِّي لَمْ أَفْعَلْهُ غِشًّا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏يُونُسُ ‏ ‏غِشًّا يَا رَسُولَ اللَّهِ ‏ ‏وَلَا نِفَاقًا قَدْ عَلِمْتُ أَنَّ اللَّهَ مُظْهِرٌ رَسُولَهُ وَمُتِمٌّ لَهُ أَمْرَهُ غَيْرَ أَنِّي كُنْتُ عَزِيزًا بَيْنَ ظَهْرِيهِمْ وَكَانَتْ وَالِدَتِي مِنْهُمْ فَأَرَدْتُ أَنْ أَتَّخِذَ هَذَا عِنْدَهُمْ فَقَالَ لَهُ ‏ ‏عُمَرُ ‏ ‏أَلَا أَضْرِبُ رَأْسَ هَذَا قَالَ ‏ ‏أَتَقْتُلُ رَجُلًا مِنْ أَهْلِ ‏ ‏بَدْرٍ ‏ ‏مَا يُدْرِيكَ لَعَلَّ اللَّهَ عَزَّ وَجَلَّ قَدْ اطَّلَعَ عَلَى أَهْلِ ‏ ‏بَدْرٍ ‏ ‏فَقَالَ اعْمَلُوا مَا شِئْتُمْ ‏","","",""],[14248,14248,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏اسْتَأْذَنَتْ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْحِجَامَةِ ‏ ‏فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَا طَيْبَةَ ‏ ‏أَنْ ‏ ‏يَحْجُمَهَا ‏ ‏قَالَ ‏ ‏حَسِبْتُ أَنَّهُ كَانَ أَخَاهَا مِنْ الرَّضَاعَةِ أَوْ غُلَامًا لَمْ ‏ ‏يَحْتَلِمْ ‏","","",""],[14249,14249,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُمْ كَانُوا إِذَا حَضَرُوا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَبَعَثَ بِالْهَدْيِ فَمَنْ شَاءَ مِنَّا أَحْرَمَ وَمَنْ شَاءَ تَرَكَ ‏","","",""],[14250,14250,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى أَنْ يُبَالَ فِي الْمَاءِ الرَّاكِدِ ‏","","",""],[14251,14251,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يَدْخُلُ النَّارَ أَحَدٌ مِمَّنْ بَايَعَ تَحْتَ الشَّجَرَةِ ‏","","",""],[14252,14252,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ رَآنِي فِي النَّوْمِ فَقَدْ رَآنِي إِنَّهُ لَا يَنْبَغِي لِلشَّيْطَانِ أَنْ يَتَمَثَّلَ فِي صُورَتِي وَقَالَ إِذَا حَلَمَ أَحَدُكُمْ فَلَا يُخْبِرَنَّ النَّاسَ بِتَلَعُّبِ الشَّيْطَانِ بِهِ فِي الْمَنَامِ ‏","","",""],[14253,14253,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا رَأَى أَحَدُكُمْ الرُّؤْيَا يَكْرَهُهَا فَلْيَبْزُقْ عَنْ يَسَارِهِ ثَلَاثًا ‏ ‏وَقَالَ ‏ ‏يُونُسُ ‏ ‏فَلْيَبْصُقْ ‏ ‏وَلْيَسْتَعِذْ بِاللَّهِ مِنْ الشَّيْطَانِ ثَلَاثًا وَلْيَتَحَوَّلْ عَنْ جَنْبِهِ الَّذِي كَانَ عَلَيْهِ ‏","","",""],[14254,14254,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ أَمَرَ رَجُلًا كَانَ يَتَصَدَّقُ بِالنَّبْلِ فِي الْمَسْجِدِ أَنْ لَا يَجِيءَ بِهَا إِلَّا وَهُوَ آخِذٌ ‏ ‏بِنُصُولِهَا ‏","","",""],[14255,14255,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ خَيْرَ مَا رُكِبَتْ إِلَيْهِ ‏ ‏الرَّوَاحِلُ ‏ ‏مَسْجِدِي ‏ ‏هَذَا ‏ ‏وَالْبَيْتُ الْعَتِيقُ ‏","","",""],[14256,14256,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ شِنْظِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءُ بْنُ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَرْسَلَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَاجَةٍ فَانْطَلَقْتُ ثُمَّ رَجَعْتُ وَقَدْ قَضَيْتُهَا فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَلَّمْتُ عَلَيْهِ فَلَمْ يَرُدَّ عَلَيَّ قَالَ فَوَقَعَ فِي نَفْسِي مَا اللَّهُ بِهِ أَعْلَمُ قَالَ قُلْتُ لَعَلَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَدَ عَلَيَّ أَنْ أَبْطَأْتُ فَسَلَّمْتُ عَلَيْهِ فَلَمْ يَرُدَّ عَلَيَّ فَوَقَعَ فِي نَفْسِي مَا اللَّهُ أَعْلَمُ أَشَدُّ مِنْ الْأُولَى ثُمَّ سَلَّمْتُ فَرَدَّ عَلَيَّ وَقَالَ ‏ ‏أَمَا إِنَّهُ لَمْ يَمْنَعْنِي أَنْ أَرُدَّ عَلَيْكَ إِلَّا أَنِّي كُنْتُ أُصَلِّي فَكَانَ عَلَى رَاحِلَتِهِ مُتَوَجِّهًا لِغَيْرِ الْقِبْلَةِ ‏","","",""],[14257,14257,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏وَاصِلٌ ‏ ‏مَوْلَى ‏ ‏أَبِي عُيَيْنَةَ ‏ ‏حَدَّثَنِي ‏ ‏خَالِدُ بْنُ عُرْفُطَةَ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ نَافِعٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَارْتَفَعَتْ رِيحُ ‏ ‏جِيفَةٍ ‏ ‏مُنْتِنَةٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَدْرُونَ مَا هَذِهِ الرِّيحُ هَذِهِ رِيحُ الَّذِينَ يَغْتَابُونَ الْمُؤْمِنِينَ ‏","","",""],[14258,14258,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابَهُ مَرُّوا بِامْرَأَةٍ فَذَبَحَتْ لَهُمْ شَاةً وَاتَّخَذَتْ لَهُمْ طَعَامًا فَلَمَّا رَجَعَ قَالَتْ يَا رَسُولَ اللَّهِ إِنَّا اتَّخَذْنَا لَكُمْ طَعَامًا فَادْخُلُوا فَكُلُوا فَدَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابُهُ وَكَانُوا لَا يَبْدَءُونَ حَتَّى يَبْتَدِئَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخَذَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لُقْمَةً فَلَمْ يَسْتَطِعْ أَنْ ‏ ‏يُسِيغَهَا ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذِهِ شَاةٌ ذُبِحَتْ بِغَيْرِ إِذْنِ أَهْلِهَا فَقَالَتْ الْمَرْأَةُ يَا نَبِيَّ اللَّهِ إِنَّا لَا نَحْتَشِمُ مِنْ آلِ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏وَلَا يَحْتَشِمُونَ مِنَّا نَأْخُذُ مِنْهُمْ وَيَأْخُذُونَ مِنَّا ‏","","",""],[14259,14259,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَمَّارٌ ‏ ‏سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏أَكَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏رُطَبًا وَشَرِبُوا مَاءً فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَا مِنْ النَّعِيمِ الَّذِي تُسْأَلُونَ عَنْهُ ‏","","",""],[14260,14260,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏وَقَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏فِي حَدِيثِهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ رَأَيْتُ كَأَنِّي فِي ‏ ‏دِرْعٍ ‏ ‏حَصِينَةٍ وَرَأَيْتُ بَقَرًا مُنَحَّرَةً ‏ ‏فَأَوَّلْتُ ‏ ‏أَنَّ ‏ ‏الدِّرْعَ ‏ ‏الْحَصِينَةَ ‏ ‏الْمَدِينَةُ ‏ ‏وَأَنَّ الْبَقَرَ هُوَ وَاللَّهِ خَيْرٌ قَالَ فَقَالَ لِأَصْحَابِهِ لَوْ أَنَّا أَقَمْنَا ‏ ‏بِالْمَدِينَةِ ‏ ‏فَإِنْ دَخَلُوا عَلَيْنَا فِيهَا قَاتَلْنَاهُمْ فَقَالُوا يَا رَسُولَ اللَّهِ وَاللَّهِ مَا دُخِلَ عَلَيْنَا فِيهَا فِي الْجَاهِلِيَّةِ فَكَيْفَ يُدْخَلُ عَلَيْنَا فِيهَا فِي الْإِسْلَامِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ فَقَالَ شَأْنَكُمْ إِذًا ‏ ‏قَالَ فَلَبِسَ لَأْمَتَهُ قَالَ فَقَالَتْ ‏ ‏الْأَنْصَارُ ‏ ‏رَدَدْنَا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأْيَهُ فَجَاءُوا فَقَالُوا يَا نَبِيَّ اللَّهِ شَأْنَكَ إِذًا فَقَالَ ‏ ‏إِنَّهُ لَيْسَ لِنَبِيٍّ إِذَا لَبِسَ لَأْمَتَهُ أَنْ يَضَعَهَا حَتَّى يُقَاتِلَ ‏","","",""],[14261,14261,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَكَثِيرُ بْنُ هِشَامٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَاجَةٍ لَهُ فَرَجَعْتُ إِلَيْهِ وَهُوَ عَلَى رَاحِلَتِهِ فَسَلَّمْتُ عَلَيْهِ فَلَمْ يَرُدَّ عَلَيَّ وَرَأَيْتُهُ يَرْكَعُ وَيَسْجُدُ فَتَنَحَّيْتُ عَنْهُ ثُمَّ قَالَ لِي مَا صَنَعْتَ فِي حَاجَتِكَ فَقُلْتُ صَنَعْتُ كَذَا وَكَذَا فَقَالَ ‏ ‏أَمَا إِنَّهُ لَمْ يَمْنَعْنِي أَنْ أَرُدَّ عَلَيْكَ إِلَّا أَنِّي كُنْتُ أُصَلِّي ‏","","",""],[14262,14262,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ الْمَدَائِنِيُّ مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏أَنْبَأَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَانْتَهَيْنَا إِلَى ‏ ‏مَشْرَعَةٍ ‏ ‏فَقَالَ أَلَا ‏ ‏تُشْرِعُ ‏ ‏يَا ‏ ‏جَابِرُ ‏ ‏قَالَ فَقُلْتُ بَلَى قَالَ فَنَزَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَشْرَعْتُ ‏ ‏قَالَ ثُمَّ ذَهَبَ لِحَاجَتِهِ وَوَضَعْتُ لَهُ وَضُوءًا فَجَاءَ ‏ ‏فَتَوَضَّأَ ثُمَّ قَامَ فَصَلَّى فِي ثَوْبٍ وَاحِدٍ خَالَفَ بَيْنَ طَرَفَيْهِ فَقُمْتُ خَلْفَهُ فَأَخَذَ بِأُذُنِي فَجَعَلَنِي عَنْ يَمِينِهِ ‏","","",""],[14263,14263,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏حَدَّثَنِي ‏ ‏ثَوْرُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَأَلَ رَجُلٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ وَقْتِ الصَّلَاةِ فَقَالَ صَلِّ مَعِي ‏ ‏فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصُّبْحَ حِينَ طَلَعَ الْفَجْرُ ثُمَّ صَلَّى الظُّهْرَ حِينَ ‏ ‏زَاغَتْ ‏ ‏الشَّمْسُ ثُمَّ صَلَّى الْعَصْرَ حِينَ كَانَ ‏ ‏فَيْءُ ‏ ‏الْإِنْسَانِ مِثْلَهُ ‏ ‏ثُمَّ صَلَّى الْمَغْرِبَ حِينَ وَجَبَتْ الشَّمْسُ ثُمَّ صَلَّى الْعِشَاءَ حِينَ غَيْبُوبَةِ ‏ ‏الشَّفَقِ ‏ ‏ثُمَّ صَلَّى الصُّبْحَ فَأَسْفَرَ ثُمَّ صَلَّى الظُّهْرَ حِينَ كَانَ ‏ ‏فَيْءُ ‏ ‏الْإِنْسَانِ مِثْلَهُ ثُمَّ صَلَّى الْعَصْرَ حِينَ كَانَ ‏ ‏فَيْءُ ‏ ‏الْإِنْسَانِ مِثْلَيْهِ ثُمَّ صَلَّى الْمَغْرِبَ قَبْلَ غَيْبُوبَةِ ‏ ‏الشَّفَقِ ‏ ‏ثُمَّ صَلَّى الْعِشَاءَ فَقَالَ بَعْضُهُمْ ثُلُثَ اللَّيْلِ وَقَالَ بَعْضُهُمْ ‏ ‏شَطْرَهُ ‏","","",""],[14264,14264,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏وَعَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏عُتْبَةَ ‏ ‏وَقَالَ ‏ ‏عَلِيٌّ ‏ ‏أَنْبَأَنَا ‏ ‏عُتْبَةُ بْنُ أَبِي حَكِيمٍ ‏ ‏حَدَّثَنِي ‏ ‏حُصَيْنُ بْنُ حَرْمَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُصَبِّحٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْخَيْلُ ‏ ‏مَعْقُودٌ ‏ ‏فِي ‏ ‏نَوَاصِيهَا ‏ ‏الْخَيْرُ وَالنَّيْلُ إِلَى يَوْمِ الْقِيَامَةِ وَأَهْلُهَا مُعَانُونَ عَلَيْهَا فَامْسَحُوا ‏ ‏بِنَوَاصِيهَا ‏ ‏وَادْعُوا لَهَا بِالْبَرَكَةِ وَقَلِّدُوهَا وَلَا تُقَلِّدُوهَا ‏ ‏بِالْأَوْتَارِ ‏ ‏وَقَالَ ‏ ‏عَلِيٌّ ‏ ‏وَلَا تُقَلِّدُوهَا الْأَوْتَارَ ‏","","",""],[14265,14265,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَطَاءٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ الْمَلِكِ بْنَ جَابِرِ بْنِ عَتِيكٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏أَخْبَرَهُ أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا حُدِّثَ الْإِنْسَانُ حَدِيثًا وَالْمُحَدِّثُ يَلْتَفِتُ حَوْلَهُ فَهُوَ أَمَانَةٌ ‏","","",""],[14266,14266,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَنْبَأَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ جَابِرٍ الْحَضْرَمِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ فِي الطَّاعُونِ الْفَارُّ مِنْهُ كَالْفَارِّ يَوْمَ الزَّحْفِ وَمَنْ صَبَرَ فِيهِ كَانَ لَهُ أَجْرُ شَهِيدٍ ‏","","",""],[14267,14267,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏حَدَّثَنَا ‏ ‏عُمَارَةُ بْنُ غَزِيَّةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَسْعَدَ بْنِ زُرَارَةَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْضِ أَسْفَارِهِ رَأَى نَاسًا مُجْتَمِعِينَ عَلَى رَجُلٍ فَسَأَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا رَجُلٌ جَهَدَهُ الصِّيَامُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ ‏ ‏الْبِرُّ ‏ ‏الصِّيَامَ فِي السَّفَرِ ‏","","",""],[14268,14268,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏أَنْبَأَنَا ‏ ‏عُبَيْدُ اللَّهِ يَعْنِي ابْنَ عَمْرٍو الرَّقِّيَّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عُمْرَةٌ فِي رَمَضَانَ تَعْدِلُ حَجَّةً ‏","","",""],[14269,14269,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَرَأَيْتَ ‏ ‏إِنْ جَاهَدْتُ فِي سَبِيلِ اللَّهِ بِنَفْسِي وَمَالِي حَتَّى أُقْتَلَ صَابِرًا ‏ ‏مُحْتَسِبًا ‏ ‏مُقْبِلًا غَيْرَ ‏ ‏مُدْبِرٍ ‏ ‏أَأَدْخُلُ الْجَنَّةَ قَالَ نَعَمْ فَلَمَّا ‏ ‏وَلَّى ‏ ‏دَعَاهُ فَقَالَ إِلَّا أَنْ يَكُونَ عَلَيْكَ دَيْنٌ لَيْسَ لَهُ عِنْدَكَ وَفَاءٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[14270,14270,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏جَاءَتْ ‏ ‏امْرَأَةُ سَعْدِ بْنِ الرَّبِيعِ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِابْنَتَيْهَا مِنْ ‏ ‏سَعْدٍ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ هَاتَانِ ابْنَتَا ‏ ‏سَعْدِ بْنِ الرَّبِيعِ ‏ ‏قُتِلَ أَبُوهُمَا مَعَكَ فِي ‏ ‏أُحُدٍ ‏ ‏شَهِيدًا وَإِنَّ عَمَّهُمَا أَخَذَ مَالَهُمَا فَلَمْ يَدَعْ لَهُمَا مَالًا وَلَا يُنْكَحَانِ إِلَّا وَلَهُمَا مَالٌ قَالَ فَقَالَ يَقْضِي اللَّهُ فِي ذَلِكَ قَالَ فَنَزَلَتْ ‏ ‏آيَةُ الْمِيرَاثِ ‏ ‏فَأَرْسَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى عَمِّهِمَا فَقَالَ ‏ ‏أَعْطِ ابْنَتَيْ ‏ ‏سَعْدٍ ‏ ‏الثُّلُثَيْنِ وَأُمَّهُمَا الثُّمُنَ وَمَا بَقِيَ فَهُوَ لَكَ ‏","","",""],[14271,14271,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏أَنْبَأَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏صَلَّى بِأَصْحَابِهِ فِي بَيْتِهِ فَقُلْنَا لَهُ صَلِّ بِنَا كَمَا رَأَيْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي قَالَ ‏ ‏فَصَلَّى بِنَا فِي مِلْحَفَةٍ فَشَدَّهَا تَحْتَ ‏ ‏الثَّنْدُوَتَيْنِ ‏ ‏وَقَالَ هَكَذَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي ‏","","",""],[14272,14272,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏أَنْبَأَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏وَحُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏بَيْنَمَا نَحْنُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي صُفُوفِنَا فِي الصَّلَاةِ صَلَاةِ الظُّهْرِ ‏ ‏أَوْ الْعَصْرِ ‏ ‏فَإِذَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَنَاوَلُ شَيْئًا ثُمَّ تَأَخَّرَ فَتَأَخَّرَ النَّاسُ فَلَمَّا قَضَى الصَّلَاةَ قَالَ لَهُ ‏ ‏أُبَيُّ بْنُ كَعْبٍ ‏ ‏شَيْئًا صَنَعْتَهُ فِي الصَّلَاةِ لَمْ تَكُنْ ‏ ‏تَصْنَعُهُ قَالَ ‏ ‏عُرِضَتْ عَلَيَّ الْجَنَّةُ بِمَا فِيهَا مِنْ الزَّهْرَةِ وَالنَّضْرَةِ فَتَنَاوَلْتُ مِنْهَا قِطْفًا مِنْ عِنَبٍ لِآتِيَكُمْ بِهِ فَحِيلَ بَيْنِي وَبَيْنَهُ وَلَوْ أَتَيْتُكُمْ بِهِ لَأَكَلَ مِنْهُ مَنْ بَيْنَ السَّمَاءِ وَالْأَرْضِ لَا يُنْقِصُونَهُ شَيْئًا ثُمَّ عُرِضَتْ عَلَيَّ النَّارُ فَلَمَّا وَجَدْتُ سَفْعَهَا تَأَخَّرْتُ عَنْهَا وَأَكْثَرُ مَنْ رَأَيْتُ فِيهَا النِّسَاءُ اللَّاتِي إِنْ اؤْتُمِنَّ أَفْشَيْنَ وَإِنْ يُسْأَلْنَ بَخِلْنَ وَإِنْ يَسْأَلْنَ ‏ ‏أَلْحَفْنَ ‏ ‏قَالَ ‏ ‏حُسَيْنٌ ‏ ‏وَإِنْ أُعْطِينَ لَمْ يَشْكُرْنَ ‏ ‏وَرَأَيْتُ فِيهَا ‏ ‏لُحَيَّ بْنَ عَمْرٍو ‏ ‏يَجُرُّ ‏ ‏قُصْبَهُ ‏ ‏فِي النَّارِ وَأَشْبَهُ مَنْ رَأَيْتُ بِهِ ‏ ‏مَعْبَدُ بْنُ أَكْثَمَ الْكَعْبِيُّ ‏ ‏قَالَ ‏ ‏مَعْبَدٌ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏أَيُخْشَى عَلَيَّ مِنْ شَبَهِهِ وَهُوَ وَالِدٌ فَقَالَ لَا أَنْتَ مُؤْمِنٌ وَهُوَ كَافِرٌ ‏ ‏قَالَ ‏ ‏حُسَيْنٌ ‏ ‏وَكَانَ أَوَّلَ مَنْ حَمَلَ ‏ ‏الْعَرَبَ ‏ ‏عَلَى عِبَادَةِ الْأَوْثَانِ ‏ ‏قَالَ ‏ ‏حُسَيْنٌ ‏ ‏تَأَخَّرْتُ عَنْهَا وَلَوْلَا ذَلِكَ لَغَشِيَتْكُمْ ‏","","",""],[14273,14273,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْجَوَّابِ ‏ ‏حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ رُزَيْقٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كَانَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏يُقَالُ لَهُ ‏ ‏أَبُو شُعَيْبٍ ‏ ‏وَكَانَ لَهُ غُلَامٌ لَحَّامٌ فَقَالَ لَهُ اجْعَلْ لَنَا طَعَامًا ‏ ‏لَعَلِّي ‏ ‏أَدْعُو رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَادِسَ سِتَّةٍ فَدَعَاهُمْ فَاتَّبَعَهُمْ رَجُلٌ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ هَذَا قَدْ اتَّبَعَنَا أَفَتَأْذَنُ لَهُ قَالَ نَعَمْ ‏","","",""],[14274,14274,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏حَدَّثَنَا ‏ ‏شُرَحْبِيلُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ ثَمَنِ الْكَلْبِ وَقَالَ طُعْمَةٌ جَاهِلِيَّةٌ ‏","","",""],[14275,14275,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏أَبَا الزُّبَيْرِ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَذْكُرُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏فِيمَا سَقَتْ الْأَنْهَارُ وَالسَّيْلُ الْعُشُورُ وَفِيمَا سُقِيَ ‏ ‏بِالسَّانِيَةِ ‏ ‏نِصْفُ الْعُشُورِ ‏","","",""],[14276,14276,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو شِهَابٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَ ‏ ‏الْجِعْرَانَةِ ‏ ‏وَهُوَ يَقْسِمُ فِضَّةً فِي ثَوْبِ ‏ ‏بِلَالٍ ‏ ‏لِلنَّاسِ فَقَالَ ‏ ‏رَجُلٌ ‏ ‏يَا رَسُولَ اللَّهِ اعْدِلْ فَقَالَ ‏ ‏وَيْلَكَ وَمَنْ يَعْدِلُ إِذَا لَمْ أَعْدِلْ لَقَدْ خِبْتُ إِنْ لَمْ أَكُنْ أَعْدِلُ فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ دَعْنِي أَقْتُلْ هَذَا الْمُنَافِقَ فَقَالَ مَعَاذَ اللَّهِ أَنْ يَتَحَدَّثَ النَّاسُ أَنِّي أَقْتُلُ أَصْحَابِي إِنَّ هَذَا وَأَصْحَابَهُ يَقْرَءُونَ الْقُرْآنَ لَا ‏ ‏يُجَاوِزُ ‏ ‏حَنَاجِرَهُمْ ‏ ‏أَوْ ‏ ‏تَرَاقِيَهُمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ ‏ ‏مُرُوقَ ‏ ‏السَّهْمِ مِنْ الرَّمِيَّةِ ‏","","",""],[14277,14277,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ ‏ ‏عَنْ ‏ ‏الرَّبِيعِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ مَوْلُودٍ يُولَدُ عَلَى الْفِطْرَةِ حَتَّى يُعْرِبَ عَنْهُ لِسَانُهُ فَإِذَا أَعْرَبَ عَنْهُ لِسَانُهُ إِمَّا شَاكِرًا وَإِمَّا كَفُورًا ‏","","",""],[14278,14278,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ مُرَّةَ ‏ ‏وَحُصَيْنُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَصَابَنَا عَطَشٌ ‏ ‏بِالْحُدَيْبِيَةِ ‏ ‏فَجَهَشْنَا ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبَيْنَ يَدَيْهِ ‏ ‏تَوْرٌ ‏ ‏فِيهِ مَاءٌ فَقَالَ بِأَصَابِعِهِ هَكَذَا فِيهَا وَقَالَ ‏ ‏خُذُوا بِسْمِ اللَّهِ قَالَ فَجَعَلَ الْمَاءُ ‏ ‏يَتَخَلَّلُ ‏ ‏مِنْ بَيْنِ أَصَابِعِهِ كَأَنَّهَا عُيُونٌ فَوَسِعَنَا وَكَفَانَا ‏ ‏وَقَالَ ‏ ‏حُصَيْنٌ ‏ ‏فِي حَدِيثِهِ فَشَرِبْنَا وَتَوَضَّأْنَا ‏","","",""],[14279,14279,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏حَجَّاجِ بْنِ أَبِي زَيْنَبَ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِعْمَ الْإِدَامُ الْخَلُّ مَا أَقْفَرَ بَيْتٌ فِيهِ خَلٌّ ‏","","",""],[14280,14280,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏نَحَرْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏سَبْعِينَ بَدَنَةً الْبَدَنَةُ عَنْ سَبْعَةٍ ‏","","",""],[14281,14281,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بِشْرٍ جَعْفَرُ بْنُ أَبِي وَحْشِيَّةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏دَعَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَا طَيْبَةَ ‏ ‏فَحَجَمَهُ ‏ ‏قَالَ فَسَأَلَهُ كَمْ ضَرِيبَتُكَ قَالَ ثَلَاثَةُ ‏ ‏آصُعٍ ‏ ‏قَالَ فَوَضَعَ عَنْهُ ‏ ‏صَاعًا ‏","","",""],[14282,14282,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏السَّائِبَةُ ‏ ‏جُبَارٌ ‏ ‏وَالْجُبُّ ‏ ‏جُبَارٌ ‏ ‏وَالْمَعْدِنُ ‏ ‏جُبَارٌ ‏ ‏وَفِي ‏ ‏الرِّكَازِ ‏ ‏الْخُمُسُ ‏ ‏قَالَ ‏ ‏و قَالَ ‏ ‏الشَّعْبِيُّ ‏ ‏الرِّكَازُ ‏ ‏الْكَنْزُ ‏ ‏الْعَادِيُّ ‏","","",""],[14283,14283,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكُمْ الْيَوْمَ عَلَى دِينٍ وَإِنِّي مُكَاثِرٌ بِكُمْ الْأُمَمَ فَلَا تَمْشُوا بَعْدِي ‏ ‏الْقَهْقَرَى ‏","","",""],[14284,14284,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ مِقْسَمٍ ‏ ‏حَدَّثَنِي ‏ ‏جَابِرُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَرَّتْ بِنَا جَنَازَةٌ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقُمْنَا مَعَهُ فَذَهَبْنَا لِنَحْمِلَهَا إِذَا هِيَ جَنَازَةُ يَهُودِيَّةٍ فَقُلْنَا يَا رَسُولَ اللَّهِ إِنَّهَا جَنَازَةُ يَهُودِيَّةٍ قَالَ ‏ ‏إِنَّ لِلْمَوْتِ ‏ ‏فَزَعًا ‏ ‏فَإِذَا رَأَيْتُمْ الْجِنَازَةَ فَقُومُوا لَهَا ‏","","",""],[14285,14285,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏وَمُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏عَطَاءٌ ‏ ‏وَقَالَ ‏ ‏ابْنُ مُصْعَبٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كَانَتْ لِرِجَالٍ فُضُولُ أَرَضِينَ فَكَانُوا يُؤَاجِرُونَهَا عَلَى الثُّلُثِ وَالرُّبُعِ وَالنِّصْفِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَتْ لَهُ أَرْضٌ فَلْيَزْرَعْهَا أَوْ لِيَمْنَحْهَا أَخَاهُ فَإِنْ أَبَى فَلْيُمْسِكْ أَرْضَهُ ‏","","",""],[14286,14286,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ ‏ ‏حَدَّثَنَا ‏ ‏مَاعِزٌ التَّمِيمِيُّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَرْشُ إِبْلِيسَ عَلَى الْبَحْرِ يَبْعَثُ سَرَايَاهُ فِي كُلِّ يَوْمٍ يَفْتِنُونَ النَّاسَ فَأَعْظَمُهُمْ عِنْدَهُ مَنْزِلَةً أَعْظَمُهُمْ فِتْنَةً لِلنَّاسِ ‏","","",""],[14287,14287,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏مَاعِزٍ التَّمِيمِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيَأْكُلُ أَهْلُ الْجَنَّةِ قَالَ نَعَمْ وَيَشْرَبُونَ وَلَا يَبُولُونَ فِيهَا وَلَا ‏ ‏يَتَغَوَّطُونَ ‏ ‏وَلَا ‏ ‏يَتَنَخَّمُونَ ‏ ‏إِنَّمَا يَكُونُ ذَلِكَ ‏ ‏جُشَاءً ‏ ‏وَرَشْحًا ‏ ‏كَرَشْحِ ‏ ‏الْمِسْكِ ‏ ‏وَيُلْهَمُونَ التَّسْبِيحَ وَالتَّحْمِيدَ كَمَا تُلْهَمُونَ النَّفَسَ ‏","","",""],[14288,14288,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ ‏ ‏عَنْ ‏ ‏مَاعِزٍ التَّمِيمِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ الشَّيْطَانَ قَدْ يَئِسَ أَنْ يَعْبُدَهُ الْمُصَلُّونَ وَلَكِنْ فِي ‏ ‏التَّحْرِيشِ ‏ ‏بَيْنَهُمْ ‏","","",""],[14289,14289,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعَيْبُ بْنُ أَبِي حَمْزَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَالَ حِينَ يَسْمَعُ النِّدَاءَ اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلَاةِ الْقَائِمَةِ آتِ ‏ ‏مُحَمَّدًا ‏ ‏الْوَسِيلَةَ وَالْفَضِيلَةَ وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي أَنْتَ وَعَدْتَهُ إِلَّا حَلَّتْ لَهُ الشَّفَاعَةُ يَوْمَ الْقِيَامَةِ ‏","","",""],[14290,14290,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ أَمِيرًا مِنْ أُمَرَاءِ الْفِتْنَةِ قَدِمَ ‏ ‏الْمَدِينَةَ ‏ ‏وَكَانَ قَدْ ذَهَبَ بَصَرُ ‏ ‏جَابِرٍ ‏ ‏فَقِيلَ ‏ ‏لِجَابِرٍ ‏ ‏لَوْ تَنَحَّيْتَ عَنْهُ فَخَرَجَ يَمْشِي بَيْنَ ابْنَيْهِ فَنُكِّبَ فَقَالَ تَعِسَ مَنْ أَخَافَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ابْنَاهُ ‏ ‏أَوْ أَحَدُهُمَا ‏ ‏يَا ‏ ‏أَبَتِ وَكَيْفَ أَخَافَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ مَاتَ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَخَافَ أَهْلَ ‏ ‏الْمَدِينَةِ ‏ ‏فَقَدْ أَخَافَ مَا بَيْنَ جَنْبَيَّ ‏","","",""],[14291,14291,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرًا ‏ ‏يَقُولُ ‏ ‏بَصَرَ عَيْنِي وَسَمِعَ أُذُنِي رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْجِعْرَانَةِ ‏ ‏وَفِي ثَوْبِ ‏ ‏بِلَالٍ ‏ ‏فِضَّةٌ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْبِضُهَا لِلنَّاسِ ‏ ‏يُعْطِيهِمْ فَقَالَ ‏ ‏رَجُلٌ ‏ ‏اعْدِلْ قَالَ وَيْلَكَ ‏ ‏وَمَنْ يَعْدِلُ إِذَا لَمْ أَكُنْ أَعْدِلُ قَالَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏يَا رَسُولَ اللَّهِ دَعْنِي أَقْتُلْ هَذَا الْمُنَافِقَ الْخَبِيثَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَاذَ اللَّهِ أَنْ يَتَحَدَّثَ النَّاسُ أَنِّي أَقْتُلُ أَصْحَابِي إِنَّ هَذَا وَأَصْحَابَهُ يَقْرَءُونَ الْقُرْآنَ لَا ‏ ‏يُجَاوِزُ ‏ ‏تَرَاقِيَهُمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏السَّهْمُ مِنْ ‏ ‏الرَّمِيَّةِ ‏","","",""],[14292,14292,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَانُ بْنُ رِفَاعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا قَسَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَنَائِمَ ‏ ‏هَوَازِنَ ‏ ‏بَيْنَ النَّاسِ ‏ ‏بِالْجِعْرَانَةِ ‏ ‏قَامَ رَجُلٌ مِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏فَقَالَ اعْدِلْ يَا ‏ ‏مُحَمَّدُ ‏ ‏فَقَالَ وَيْلَكَ ‏ ‏وَمَنْ يَعْدِلُ إِذَا لَمْ أَعْدِلْ لَقَدْ خِبْتُ وَخَسِرْتُ إِنْ لَمْ أَعْدِلْ قَالَ فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ أَلَا أَقُومُ فَأَقْتُلَ هَذَا الْمُنَافِقَ قَالَ مَعَاذَ اللَّهِ أَنْ تَتَسَامَعَ الْأُمَمُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏يَقْتُلُ أَصْحَابَهُ ثُمَّ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ هَذَا وَأَصْحَابًا لَهُ يَقْرَءُونَ الْقُرْآنَ لَا ‏ ‏يُجَاوِزُ ‏ ‏تَرَاقِيَهُمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏الْمِرْمَاةُ مِنْ ‏ ‏الرَّمِيَّةِ ‏ ‏قَالَ ‏ ‏مُعَاذٌ ‏ ‏فَقَالَ ‏ ‏لِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏فَعَرَضْتُ هَذَا الْحَدِيثَ عَلَى ‏ ‏الزُّهْرِيِّ ‏ ‏فَمَا خَالَفَنِي إِلَّا أَنَّهُ قَالَ ‏ ‏النَّضِيَّ قُلْتُ الْقِدْحَ فَقَالَ أَلَسْتَ بِرَجُلٍ عَرَبِيٍّ ‏","","",""],[14293,14293,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ رَبِّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنِي ‏ ‏الزُّبَيْدِيُّ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبَانَ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أُرِيَ اللَّيْلَةَ رَجُلٌ صَالِحٌ أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏نِيطَ ‏ ‏بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنِيطَ ‏ ‏عُمَرُ ‏ ‏بِأَبِي بَكْرٍ ‏ ‏وَنِيطَ ‏ ‏عُثْمَانُ ‏ ‏بِعُمَرَ ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏فَلَمَّا قُمْنَا مِنْ عِنْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْنَا أَمَّا الرَّجُلُ الصَّالِحُ فَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَمَّا ذِكْرُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏نَوْطِ ‏ ‏بَعْضِهِمْ لِبَعْضٍ فَهُمْ وُلَاةُ هَذَا الْأَمْرِ الَّذِي بَعَثَ اللَّهُ بِهِ نَبِيَّهُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[14294,14294,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏سَيَّارٌ أَبُو الْحَكَمِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الشَّعْبِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ أَحَدُكُمْ لَيْلًا فَلَا يَأْتِ أَهْلَهُ ‏ ‏طُرُوقًا ‏ ‏كَيْ ‏ ‏تَسْتَحِدَّ ‏ ‏الْمُغِيبَةُ ‏ ‏وَتَمْتَشِطَ ‏ ‏الشَّعِثَةُ ‏","","",""],[14295,14295,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏وَحُجَيْنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كُنَّا يَوْمَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏أَلْفًا وَأَرْبَعَ مِائَةٍ فَبَايَعْنَاهُ ‏ ‏وَعُمَرُ ‏ ‏آخِذٌ بِيَدِهِ تَحْتَ الشَّجَرَةِ وَهِيَ سَمُرَةٌ وَقَالَ ‏ ‏بَايَعْنَاهُ عَلَى أَنْ لَا نَفِرَّ وَلَمْ نُبَايِعْهُ عَلَى الْمَوْتِ ‏","","",""],[14296,14296,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏صَالِحُ بْنُ مُسْلِمِ بْنِ رُومَانَ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ مُحَمَّدُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ أَنَّ رَجُلًا أَعْطَى امْرَأَةً صَدَاقًا مِلْءَ يَدَيْهِ طَعَامًا كَانَتْ لَهُ حَلَالًا ‏","","",""],[14297,14297,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْحَارِثِ ‏ ‏أَوْ ‏ ‏ابْنِ أَبِي الْحَارِثِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَجُلٌ مِنْ أَصْحَابِهِ عَلَى رَجُلٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فِي ‏ ‏حَائِطٍ ‏ ‏وَهُوَ ‏ ‏يُحَوِّلُ ‏ ‏الْمَاءَ فَقَالَ هَلْ عِنْدَكَ مَاءٌ بَاتَ هَذِهِ اللَّيْلَةَ فِي ‏ ‏شَنٍّ ‏ ‏وَإِلَّا ‏ ‏كَرَعْنَا ‏ ‏قَالَ نَعَمْ يَا رَسُولَ اللَّهِ فَانْطَلَقَ بِهِ إِلَى ‏ ‏الْعَرِيشِ ‏ ‏فَحَلَبَ لَهُ شَاةً ثُمَّ صَبَّ عَلَيْهِ مَاءً بَاتَ فِي ‏ ‏شَنٍّ ‏ ‏فَشَرِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسَقَى صَاحِبَهُ ‏","","",""],[14298,14298,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَيْثُ ‏ ‏أَفَاضَ ‏ ‏مِنْ ‏ ‏عَرَفَةَ ‏ ‏جَعَلَ يَقُولُ بِيَدِهِ ‏ ‏السَّكِينَةَ ‏ ‏عِبَادَ اللَّهِ ‏ ‏السَّكِينَةَ ‏ ‏عِبَادَ اللَّهِ ‏","","",""],[14299,14299,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى عَلَى ‏ ‏النَّجَاشِيِّ ‏ ‏وَصَفَفْنَا خَلْفَهُ صَفَّيْنِ ‏","","",""],[14300,14300,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏قَيْسُ بْنُ سُلَيْمٍ الْعَنْبَرِيُّ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ الْفَقِيرُ ‏ ‏حَدَّثَنَا ‏ ‏جَابِرُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ قَوْمًا يَخْرُجُونَ مِنْ النَّارِ يَحْتَرِقُونَ فِيهَا إِلَّا ‏ ‏دَارَاتِ ‏ ‏وُجُوهِهِمْ حَتَّى يَدْخُلُوا الْجَنَّةَ ‏","","",""],[14301,14301,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنَ الْهَادِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ عَبْدِ اللَّهِ بْنِ الْحَكَمِ ‏ ‏عَنْ ‏ ‏الْقَعْقَاعِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏غَطُّوا الْإِنَاءَ ‏ ‏وَأَوْكِئُوا ‏ ‏السِّقَاءَ ‏ ‏فَإِنَّ فِي السَّنَةِ لَيْلَةً يَنْزِلُ فِيهَا وَبَاءٌ لَا يَمُرُّ بِإِنَاءٍ لَمْ يُغَطَّ وَلَا ‏ ‏سِقَاءٍ ‏ ‏لَمْ ‏ ‏يُوكَ ‏ ‏إِلَّا وَقَعَ فِيهِ مِنْ ذَلِكَ الْوَبَاءِ ‏","","",""],[14302,14302,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنَ الْهَادِ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَلِيِّ بْنِ الْحُسَيْنِ ‏ ‏أَنَّهُ قَالَ ‏ ‏بَلَغَنِي أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَقِلُّوا الْخُرُوجَ ‏ ‏بَعْدَ ‏ ‏هَدْأَةٍ فَإِنَّ لِلَّهِ عَزَّ وَجَلَّ خَلْقًا يَبُثُّهُمْ فَإِذَا سَمِعْتُمْ نُبَاحَ الْكَلْبِ أَوْ ‏ ‏نُهَاقَ الْحُمُرِ فَاسْتَعِيذُوا بِاللَّهِ مِنْ الشَّيْطَانِ ‏ ‏و قَالَ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ قَالَ ‏ ‏يَزِيدُ ‏ ‏وَحَدَّثَنِي ‏ ‏هَذَا الْحَدِيثَ ‏ ‏شُرَحْبِيلُ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ إِنَّهُ سَمِعَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[14303,14303,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَيَّانَ أَبُو خَالِدٍ يَعْنِي الْأَحْمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏رَمَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِ حَصَى ‏ ‏الْخَذْفِ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَيَّانَ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏لَا أَدْرِي بِكَمْ رَمَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[14304,14304,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُجَاهِدًا ‏ ‏يَقُولُ عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ نَقُولُ لَبَّيْكَ بِالْحَجِّ ‏ ‏فَأَمَرَنَا فَجَعَلْنَاهَا عُمْرَةً ‏","","",""],[14305,14305,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏وَعَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏تَمَتَّعْنَا مُتْعَتَيْنِ عَلَى عَهْدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحَجَّ وَالنِّسَاءَ ‏ ‏فَنَهَانَا ‏ ‏عُمَرُ ‏ ‏عَنْهُمَا فَانْتَهَيْنَا ‏","","",""],[14306,14306,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمَلِيحِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏إِنَّ أَوَّلَ خَبَرٍ قَدِمَ عَلَيْنَا عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ امْرَأَةً كَانَ لَهَا ‏ ‏تَابِعٌ ‏ ‏قَالَ فَأَتَاهَا فِي صُورَةِ طَيْرٍ فَوَقَعَ عَلَى جِذْعٍ لَهُمْ قَالَ فَقَالَتْ أَلَا تَنْزِلُ فَنُخْبِرَكَ وَتُخْبِرَنَا قَالَ إِنَّهُ قَدْ خَرَجَ رَجُلٌ ‏ ‏بِمَكَّةَ ‏ ‏حَرَّمَ عَلَيْنَا الزِّنَا وَمَنَعَ مِنْ ‏ ‏الْفِرَارِ ‏","","",""],[14307,14307,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا ‏ ‏يُبَاشِرْ ‏ ‏الرَّجُلُ الرَّجُلَ فِي الثَّوْبِ الْوَاحِدِ وَلَا ‏ ‏تُبَاشِرْ ‏ ‏الْمَرْأَةُ الْمَرْأَةَ فِي الثَّوْبِ الْوَاحِدِ ‏","","",""],[14308,14308,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏أَخْبَرَنِي ‏ ‏مَوْلَايَ ‏ ‏الْمُطَّلِبُ بْنُ عَبْدِ اللَّهِ بْنِ حَنْطَبٍ ‏ ‏أَنَّ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِيدَ الْأَضْحَى فَلَمَّا انْصَرَفَ أَتَى بِكَبْشٍ فَذَبَحَهُ فَقَالَ ‏ ‏بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ اللَّهُمَّ إِنَّ هَذَا عَنِّي وَعَمَّنْ لَمْ يُضَحِّ مِنْ أُمَّتِي ‏","","",""],[14309,14309,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمَلِيحِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عَقِيلِ بْنِ أَبِي طَالِبٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَطْلُعُ عَلَيْكُمْ مِنْ تَحْتِ هَذَا السُّورِ رَجُلٌ مِنْ أَهْلِ الْجَنَّةِ قَالَ فَطَلَعَ عَلَيْهِمْ ‏ ‏أَبُو بَكْرٍ ‏ ‏رِضْوَانُ اللَّهِ عَلَيْهِ فَهَنَّأْنَاهُ بِمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ لَبِثَ ‏ ‏هُنَيْهَةً ‏ ‏ثُمَّ قَالَ يَطْلُعُ عَلَيْكُمْ مِنْ تَحْتِ هَذَا السُّورِ رَجُلٌ مِنْ أَهْلِ الْجَنَّةِ قَالَ فَطَلَعَ ‏ ‏عُمَرُ ‏ ‏قَالَ فَهَنَّأْنَاهُ بِمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ثُمَّ قَالَ يَطْلُعُ عَلَيْكُمْ مِنْ تَحْتِ هَذَا السُّورِ رَجُلٌ مِنْ أَهْلِ الْجَنَّةِ اللَّهُمَّ إِنْ شِئْتَ جَعَلْتَهُ ‏ ‏عَلِيًّا ‏ ‏ثَلَاثَ مَرَّاتٍ فَطَلَعَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏","","",""],[14310,14310,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَيَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَحْيَا أَرْضًا مَيْتَةً فَلَهُ فِيهَا أَجْرٌ وَمَا أَكَلَتْ ‏ ‏الْعَافِيَةُ ‏ ‏مِنْهَا فَهُوَ لَهُ ‏ ‏صَدَقَةٌ ‏ ‏وَقَالَ ‏ ‏ابْنُ أَبِي بُكَيْرٍ ‏ ‏مَنْ أَحْيَا أَرْضًا مَيْتَةً فَهِيَ لَهُ ‏","","",""],[14311,14311,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَحَسَنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالُوا ثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي ‏ ‏حَدِيثِهِ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏ذَبَحْنَا يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏الْخَيْلَ وَالْبِغَالَ وَالْحَمِيرَ فَنَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْبِغَالِ وَالْحَمِيرِ وَلَمْ يَنْهَنَا عَنْ الْخَيْلِ ‏","","",""],[14312,14312,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ ‏ ‏الْمُزَابَنَةِ ‏ ‏وَالْمُحَاقَلَةِ ‏ ‏وَالْمُخَابَرَةِ ‏ ‏وَالثُّنْيَا ‏ ‏وَالْمُعَاوَمَةِ ‏","","",""],[14313,14313,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏فِيمَا أَحْسِبُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ بَيْعِ الْمَاءِ ‏","","",""],[14314,14314,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَالنَّقِيرِ ‏","","",""],[14315,14315,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي ثَوْبٍ وَاحِدٍ ‏ ‏مُتَوَشِّحًا ‏ ‏بِهِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏قَدْ خَالَفَ بَيْنَ طَرَفَيْهِ ‏","","",""],[14316,14316,"","","‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرُ بْنُ سُلَيْمَانَ الرَّقِّيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏الْعُمْرَةُ أَوَاجِبَةٌ هِيَ قَالَ لَا ‏","","",""],[14317,14317,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْقُدُّوسِ بْنُ بَكْرِ بْنِ خُنَيْسٍ ‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏جَابِرٌ ‏ ‏عَمَّا يُدْعَى لِلْمَيِّتِ فَقَالَ مَا أَبَاحَ لَنَا فِيهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا ‏ ‏أَبُو بَكْرٍ ‏ ‏وَلَا ‏ ‏عُمَرُ ‏","","",""],[14318,14318,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ حُمَيْدٍ أَبُو سُفْيَانَ يَعْنِي الْمَعْمَرِيَّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏وَأَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْكَافِرَ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ وَالْمُؤْمِنُ يَأْكُلُ فِي مِعًى وَاحِدٍ ‏","","",""],[14319,14319,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَنْ رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي ثَوْبٍ وَاحِدٍ قَدْ خَالَفَ بَيْنَ طَرَفَيْهِ ‏","","",""],[14320,14320,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ ثَابِتٍ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُؤَمَّلِ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَاءُ ‏ ‏زَمْزَمَ ‏ ‏لِمَا شُرِبَ لَهُ ‏","","",""],[14321,14321,"","","‏ ‏حَدَّثَنَا ‏ ‏مِسْكِينُ بْنُ بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏حَسَّانَ بْنِ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏أَتَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَائِرًا فِي مَنْزِلِنَا فَرَأَى رَجُلًا ‏ ‏شَعِثًا ‏ ‏فَقَالَ ‏ ‏أَمَا كَانَ يَجِدُ هَذَا مَا يُسَكِّنُ بِهِ رَأْسَهُ وَرَأَى رَجُلًا عَلَيْهِ ثِيَابٌ وَسِخَةٌ فَقَالَ أَمَا كَانَ يَجِدُ هَذَا مَا يَغْسِلُ بِهِ ثِيَابَهُ ‏","","",""],[14322,14322,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْمُزَفَّتِ ‏","","",""],[14323,14323,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏و حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏أَنْبَأَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عَقِيلِ بْنِ أَبِي طَالِبٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَفَّنَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَمْزَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فِي ثَوْبٍ وَاحِدٍ ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏ذَلِكَ الثَّوْبُ ‏ ‏نَمِرَةٌ ‏","","",""],[14324,14324,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مَثَلَ هَذِهِ الصَّلَوَاتِ الْخَمْسِ مَثَلُ نَهَرٍ جَارٍ عَلَى بَابِ أَحَدِكُمْ يَغْتَسِلُ فِيهِ كُلَّ يَوْمٍ خَمْسَ مَرَّاتٍ فَمَا يُبْقِي ذَلِكَ مِنْ ‏ ‏الدَّنَسِ ‏","","",""],[14325,14325,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الْيَشْكُرِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ كَانَ لَهُ شَرِيكٌ فِي ‏ ‏حَائِطٍ ‏ ‏فَلَا يَبِعْهُ حَتَّى يَعْرِضَهُ عَلَيْهِ ‏","","",""],[14326,14326,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ يَعْنِي ابْنَ عَطَاءٍ ‏ ‏أَنْبَأَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ اللَّيْثِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏دَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَسْجِدَ فَإِذَا فِيهِ قَوْمٌ يَقْرَءُونَ الْقُرْآنَ قَالَ ‏ ‏اقْرَءُوا الْقُرْآنَ وَابْتَغُوا بِهِ اللَّهَ عَزَّ وَجَلَّ مِنْ قَبْلِ أَنْ يَأْتِيَ قَوْمٌ يُقِيمُونَهُ إِقَامَةَ ‏ ‏الْقِدْحِ ‏ ‏يَتَعَجَّلُونَهُ وَلَا يَتَأَجَّلُونَهُ ‏","","",""],[14327,14327,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَرْتَدُوا ‏ ‏الصَّمَّاءَ ‏ ‏فِي ثَوْبٍ وَاحِدٍ وَلَا يَأْكُلْ أَحَدُكُمْ بِشِمَالِهِ وَلَا يَمْشِ فِي نَعْلٍ وَاحِدَةٍ وَلَا ‏ ‏يَحْتَبِ ‏ ‏فِي ثَوْبٍ وَاحِدٍ ‏","","",""],[14328,14328,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏احْتَجَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُحْرِمٌ مِنْ أَلَمٍ كَانَ بِظَهْرِهِ ‏ ‏أَوْ بِوَرِكِهِ شَكَّ ‏ ‏هِشَامٌ ‏","","",""],[14329,14329,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ النَّخْلِ حَتَّى يُطْعَمَ ‏","","",""],[14330,14330,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ بْنُ حُمَيْدٍ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏التَّسْبِيحُ فِي الصَّلَاةِ لِلرِّجَالِ وَالتَّصْفِيقُ لِلنِّسَاءِ ‏","","",""],[14331,14331,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ ‏ ‏حَدَّثَنِي ‏ ‏الْأَسْوَدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏نُبَيْحٍ الْعَنَزِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَافَرْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَحَضَرَتْ الصَّلَاةُ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ فِي الْقَوْمِ مِنْ طَهُورٍ قَالَ فَجَاءَ رَجُلٌ بِفَضْلَةٍ فِي ‏ ‏إِدَاوَةٍ ‏ ‏قَالَ فَصَبَّهُ فِي ‏ ‏قَدَحٍ ‏ ‏قَالَ فَتَوَضَّأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ إِنَّ الْقَوْمَ أَتَوْا بَقِيَّةَ الطَّهُورِ فَقَالُوا تَمَسَّحُوا تَمَسَّحُوا قَالَ فَسَمِعَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ عَلَى رِسْلِكُمْ قَالَ ‏ ‏فَضَرَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَهُ فِي ‏ ‏الْقَدَحِ ‏ ‏فِي جَوْفِ الْمَاءِ قَالَ ثُمَّ قَالَ ‏ ‏أَسْبِغُوا ‏ ‏الْوُضُوءَ الطَّهُورَ قَالَ فَقَالَ ‏ ‏جَابِرُ بْنُ عَبْدِ اللَّهِ ‏ ‏وَالَّذِي أَذْهَبَ بَصَرِي ‏ ‏قَالَ وَكَانَ قَدْ ذَهَبَ بَصَرُهُ ‏ ‏لَقَدْ رَأَيْتُ الْمَاءَ يَخْرُجُ مِنْ بَيْنِ أَصَابِعِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يَرْفَعْ يَدَهُ حَتَّى تَوَضَّئُوا أَجْمَعُونَ ‏ ‏قَالَ ‏ ‏الْأَسْوَدُ ‏ ‏حَسِبْتُهُ قَالَ كُنَّا مِائَتَيْنِ أَوْ زِيَادَةً ‏","","",""],[14332,14332,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ ‏ ‏حَدَّثَنِي ‏ ‏الْأَسْوَدُ ‏ ‏عَنْ ‏ ‏نُبَيْحٍ الْعَنَزِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏جَابِرُ ‏ ‏أَلَكَ امْرَأَةٌ قَالَ قُلْتُ نَعَمْ قَالَ ‏ ‏أَثَيِّبًا ‏ ‏نَكَحْتَ أَمْ ‏ ‏بِكْرًا ‏ ‏قَالَ قُلْتُ لَهُ تَزَوَّجْتُهَا وَهِيَ ‏ ‏ثَيِّبٌ ‏ ‏قَالَ فَقَالَ لِي فَهَلَّا تَزَوَّجْتَهَا ‏ ‏جُوَيْرِيَةً ‏ ‏قَالَ قُلْتُ لَهُ قُتِلَ أَبِي مَعَكَ يَوْمَ كَذَا وَكَذَا وَتَرَكَ ‏ ‏جَوَارِيَ ‏ ‏فَكَرِهْتُ أَنْ أَضُمَّ إِلَيْهِنَّ ‏ ‏جَارِيَةً ‏ ‏كَإِحْدَاهُنَّ فَتَزَوَّجْتُ ‏ ‏ثَيِّبًا ‏ ‏تَقْصَعُ ‏ ‏قَمْلَةَ إِحْدَاهُنَّ وَتَخِيطُ ‏ ‏دِرْعَ ‏ ‏إِحْدَاهُنَّ إِذَا تَخَرَّقَ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِنَّكَ نِعْمَ مَا رَأَيْتَ ‏","","",""],[14333,14333,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ ‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏نُبَيْحٍ الْعَنَزِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى أَحَدَنَا إِذَا جَاءَ مِنْ سَفَرٍ أَنْ يَطْرُقَ أَهْلَهُ قَالَ فَطَرَقْنَاهُنَّ بَعْدُ ‏","","",""],[14334,14334,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ ‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏نُبَيْحٍ الْعَنَزِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏حَدَّثَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ أَرَادَ الْغَزْوَ فَقَالَ يَا مَعْشَرَ ‏ ‏الْمُهَاجِرِينَ ‏ ‏وَالْأَنْصَارِ ‏ ‏إِنَّ مِنْ إِخْوَانِكُمْ قَوْمًا لَيْسَ لَهُمْ مَالٌ وَلَا عَشِيرَةٌ فَلْيَضُمَّ أَحَدُكُمْ إِلَيْهِ الرَّجُلَيْنِ أَوْ الثَّلَاثَةَ فَمَا لِأَحَدِنَا مِنْ ظَهْرِ جَمَلِهِ إِلَّا عُقْبَةٌ كَعُقْبَةِ أَحَدِهِمْ قَالَ فَضَمَمْتُ اثْنَيْنِ أَوْ ثَلَاثَةً إِلَيَّ وَمَا لِي إِلَّا عُقْبَةٌ كَعُقْبَةِ أَحَدِهِمْ مِنْ جَمَلِي ‏","","",""],[14335,14335,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ ‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏نُبَيْحٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏فَقَدْتُ جَمَلِي لَيْلَةً فَمَرَرْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَشُدُّ ‏ ‏لِعَائِشَةَ ‏ ‏قَالَ فَقَالَ لِي مَا لَكَ يَا ‏ ‏جَابِرُ ‏ ‏قَالَ قُلْتُ فَقَدْتُ جَمَلِي ‏ ‏أَوْ ذَهَبَ جَمَلِي ‏ ‏فِي لَيْلَةٍ ظَلْمَاءَ قَالَ فَقَالَ لِي هَذَا جَمَلُكَ اذْهَبْ فَخُذْهُ قَالَ فَذَهَبْتُ نَحْوًا مِمَّا قَالَ لِي فَلَمْ أَجِدْهُ قَالَ فَرَجَعْتُ إِلَيْهِ فَقُلْتُ يَا نَبِيَّ اللَّهِ مَا وَجَدْتُهُ قَالَ فَقَالَ لِي هَذَا جَمَلُكَ اذْهَبْ فَخُذْهُ قَالَ فَذَهَبْتُ نَحْوًا مِمَّا قَالَ لِي فَلَمْ أَجِدْهُ قَالَ فَرَجَعْتُ إِلَيْهِ فَقُلْتُ بِأَبِي وَأُمِّي يَا نَبِيَّ اللَّهِ لَا وَاللَّهِ مَا وَجَدْتُهُ قَالَ فَقَالَ لِي عَلَى رِسْلِكَ حَتَّى إِذَا فَرَغَ أَخَذَ بِيَدِي فَانْطَلَقَ بِي حَتَّى أَتَيْنَا الْجَمَلَ فَدَفَعَهُ إِلَيَّ قَالَ هَذَا جَمَلُكَ قَالَ وَقَدْ سَارَ النَّاسُ قَالَ فَبَيْنَمَا أَنَا أَسِيرُ عَلَى جَمَلِي فِي عُقْبَتِي قَالَ وَكَانَ جَمَلًا فِيهِ ‏ ‏قِطَافٌ ‏ ‏قَالَ قُلْتُ يَا لَهْفَ أُمِّي أَنْ يَكُونَ لِي إِلَّا جَمَلٌ ‏ ‏قَطُوفٌ ‏ ‏قَالَ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدِي يَسِيرُ قَالَ فَسَمِعَ مَا قُلْتُ قَالَ فَلَحِقَ بِي فَقَالَ مَا قُلْتَ يَا ‏ ‏جَابِرُ ‏ ‏قَبْلُ قَالَ فَنَسِيتُ مَا قُلْتُ قَالَ قُلْتُ مَا قُلْتُ شَيْئًا يَا نَبِيَّ اللَّهِ قَالَ فَذَكَرْتُ مَا قُلْتُ قَالَ قُلْتُ يَا نَبِيَّ اللَّهِ يَا لَهْفَاهُ أَنْ يَكُونَ لِي إِلَّا جَمَلٌ ‏ ‏قَطُوفٌ ‏ ‏قَالَ فَضَرَبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَجُزَ ‏ ‏الْجَمَلِ بِسَوْطٍ ‏ ‏أَوْ بِسَوْطِي ‏ ‏قَالَ فَانْطَلَقَ أَوْضَعَ ‏ ‏أَوْ أَسْرَعَ ‏ ‏جَمَلٍ رَكِبْتُهُ قَطُّ وَهُوَ يُنَازِعُنِي ‏ ‏خِطَامَهُ ‏ ‏قَالَ فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْتَ بَائِعِي جَمَلَكَ هَذَا قَالَ قُلْتُ نَعَمْ قَالَ بِكَمْ قَالَ قُلْتُ ‏ ‏بِوُقِيَّةٍ ‏ ‏قَالَ قَالَ لِي ‏ ‏بَخٍ ‏ ‏بَخٍ ‏ ‏كَمْ فِي ‏ ‏أُوقِيَّةٍ ‏ ‏مِنْ ‏ ‏نَاضِحٍ ‏ ‏وَنَاضِحٍ ‏ ‏قَالَ قُلْتُ يَا نَبِيَّ اللَّهِ مَا ‏ ‏بِالْمَدِينَةِ ‏ ‏نَاضِحٌ ‏ ‏أُحِبُّ أَنَّهُ لَنَا مَكَانَهُ قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ أَخَذْتُهُ ‏ ‏بِوُقِيَّةٍ ‏ ‏قَالَ فَنَزَلْتُ عَنْ ‏ ‏الرَّحْلِ ‏ ‏إِلَى الْأَرْضِ قَالَ مَا شَأْنُكَ قَالَ قُلْتُ جَمَلُكَ قَالَ قَالَ لِي ارْكَبْ جَمَلَكَ قَالَ قُلْتُ مَا هُوَ بِجَمَلِي وَلَكِنَّهُ جَمَلُكَ قَالَ كُنَّا نُرَاجِعُهُ مَرَّتَيْنِ فِي الْأَمْرِ إِذَا أَمَرَنَا بِهِ فَإِذَا أَمَرَنَا الثَّالِثَةَ ‏ ‏لَمْ نُرَاجِعْهُ قَالَ فَرَكِبْتُ الْجَمَلَ حَتَّى أَتَيْتُ عَمَّتِي ‏ ‏بِالْمَدِينَةِ ‏ ‏قَالَ وَقُلْتُ لَهَا أَلَمْ تَرَيْ أَنِّي بِعْتُ ‏ ‏نَاضِحَنَا ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأُوقِيَّةٍ ‏ ‏قَالَ فَمَا رَأَيْتُهَا أَعْجَبَهَا ذَلِكَ قَالَ وَكَانَ ‏ ‏نَاضِحًا ‏ ‏فَارِهًا قَالَ ثُمَّ أَخَذْتُ شَيْئًا مِنْ ‏ ‏خَبَطٍ ‏ ‏أَوْجَرْتُهُ ‏ ‏إِيَّاهُ ثُمَّ أَخَذْتُ ‏ ‏بِخِطَامِهِ ‏ ‏فَقُدْتُهُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَجَدْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُقَاوِمًا رَجُلًا يُكَلِّمُهُ قَالَ قُلْتُ دُونَكَ يَا نَبِيَّ اللَّهِ جَمَلَكَ قَالَ فَأَخَذَ ‏ ‏بِخِطَامِهِ ‏ ‏ثُمَّ نَادَى ‏ ‏بِلَالًا ‏ ‏فَقَالَ زِنْ ‏ ‏لِجَابِرٍ ‏ ‏أُوقِيَّةً ‏ ‏وَأَوْفِهِ فَانْطَلَقْتُ مَعَ ‏ ‏بِلَالٍ ‏ ‏فَوَزَنَ لِي ‏ ‏أُوقِيَّةً ‏ ‏وَأَوْفَى مِنْ الْوَزْنِ قَالَ فَرَجَعْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ قَائِمٌ يُحَدِّثُ ذَلِكَ الرَّجُلَ قَالَ قُلْتُ لَهُ قَدْ وَزَنَ لِي ‏ ‏أُوقِيَّةً ‏ ‏وَأَوْفَانِي قَالَ فَبَيْنَمَا هُوَ كَذَلِكَ إِذْ ذَهَبْتُ إِلَى بَيْتِي وَلَا أَشْعُرُ قَالَ فَنَادَى أَيْنَ ‏ ‏جَابِرٌ ‏ ‏قَالُوا ذَهَبَ إِلَى أَهْلِهِ قَالَ أَدْرِكْ ائْتِنِي بِهِ قَالَ فَأَتَانِي رَسُولُهُ ‏ ‏يَسْعَى قَالَ يَا ‏ ‏جَابِرُ ‏ ‏يَدْعُوكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَأَتَيْتُهُ فَقَالَ فَخُذْ جَمَلَكَ قُلْتُ مَا هُوَ جَمَلِي وَإِنَّمَا هُوَ جَمَلُكَ يَا رَسُولَ اللَّهِ قَالَ خُذْ جَمَلَكَ قُلْتُ مَا هُوَ جَمَلِي إِنَّمَا هُوَ جَمَلُكَ يَا رَسُولَ اللَّهِ قَالَ خُذْ جَمَلَكَ قَالَ فَأَخَذْتُهُ قَالَ فَقَالَ ‏ ‏لَعَمْرِي مَا نَفَعْنَاكَ لِنُنْزِلَكَ عَنْهُ قَالَ فَجِئْتُ إِلَى عَمَّتِي ‏ ‏بِالنَّاضِحِ ‏ ‏مَعِي ‏ ‏وَبِالْوَقِيَّةِ ‏ ‏قَالَ فَقُلْتُ لَهَا مَا تَرَيْنَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْطَانِي ‏ ‏أُوقِيَّةً ‏ ‏وَرَدَّ عَلَيَّ جَمَلِي ‏","","",""],[14336,14336,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏صَدَقَةُ بْنُ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَقِيلِ بْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏فِيمَا يَذْكُرُ مِنْ اجْتِهَادِ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْعِبَادَةِ قَالَ خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَفِي مَوْضِعٍ آخَرَ خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزْوَةٍ مِنْ ‏ ‏نَجْدٍ ‏ ‏فَأَصَابَ امْرَأَةَ رَجُلٍ مِنْ الْمُشْرِكِينَ ‏ ‏إِلَى ‏ ‏نَجْدٍ ‏ ‏فَغَشِينَا دَارًا مِنْ دُورِ الْمُشْرِكِينَ قَالَ فَأَصَبْنَا امْرَأَةَ رَجُلٍ مِنْهُمْ قَالَ ثُمَّ انْصَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَاجِعًا وَجَاءَ صَاحِبُهَا وَكَانَ غَائِبًا فَذُكِرَ لَهُ مُصَابُهَا فَحَلَفَ لَا يَرْجِعُ حَتَّى ‏ ‏يُهْرِيقَ ‏ ‏فِي ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَمًا قَالَ فَلَمَّا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِبَعْضِ الطَّرِيقِ نَزَلَ فِي ‏ ‏شِعْبٍ ‏ ‏مِنْ ‏ ‏الشِّعَابِ ‏ ‏وَقَالَ ‏ ‏مَنْ رَجُلَانِ ‏ ‏يَكْلَآَنَا ‏ ‏فِي لَيْلَتِنَا هَذِهِ مِنْ عَدُوِّنَا قَالَ فَقَالَ رَجُلٌ مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏وَرَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏نَحْنُ ‏ ‏نَكْلَؤُكَ ‏ ‏يَا رَسُولَ اللَّهِ قَالَ فَخَرَجَا إِلَى ‏ ‏فَمِ ‏ ‏الشِّعْبِ ‏ ‏دُونَ الْعَسْكَرِ ثُمَّ قَالَ الْأَنْصَارِيُّ ‏ ‏لِلْمُهَاجِرِيِّ ‏ ‏أَتَكْفِينِي ‏ ‏أَوَّلَ اللَّيْلِ ‏ ‏وَأَكْفِيكَ ‏ ‏آخِرَهُ أَمْ ‏ ‏تَكْفِينِي ‏ ‏آخِرَهُ ‏ ‏وَأَكْفِيكَ ‏ ‏أَوَّلَهُ قَالَ فَقَالَ ‏ ‏الْمُهَاجِرِيُّ بَلْ ‏ ‏اكْفِنِي ‏ ‏أَوَّلَهُ ‏ ‏وَأَكْفِيكَ ‏ ‏آخِرَهُ فَنَامَ ‏ ‏الْمُهَاجِرِيُّ وَقَامَ الْأَنْصَارِيُّ ‏ ‏يُصَلِّي قَالَ فَافْتَتَحَ سُورَةً مِنْ الْقُرْآنِ فَبَيْنَا هُوَ فِيهَا يَقْرَأُ إِذْ جَاءَ زَوْجُ الْمَرْأَةِ قَالَ فَلَمَّا رَأَى الرَّجُلَ قَائِمًا عَرَفَ أَنَّهُ ‏ ‏رَبِيئَةُ ‏ ‏الْقَوْمِ فَيَنْتَزِعُ لَهُ بِسَهْمٍ فَيَضَعُهُ فِيهِ قَالَ فَيَنْزِعُهُ فَيَضَعُهُ وَهُوَ قَائِمٌ يَقْرَأُ فِي السُّورَةِ الَّتِي هُوَ فِيهَا وَلَمْ يَتَحَرَّكْ كَرَاهِيَةَ أَنْ يَقْطَعَهَا قَالَ ثُمَّ عَادَ لَهُ زَوْجُ الْمَرْأَةِ بِسَهْمٍ آخَرَ فَوَضَعَهُ فِيهِ فَانْتَزَعَهُ فَوَضَعَهُ وَهُوَ قَائِمٌ ‏ ‏يُصَلِّي وَلَمْ يَتَحَرَّكْ كَرَاهِيَةَ أَنْ يَقْطَعَهَا قَالَ ثُمَّ عَادَ لَهُ زَوْجُ الْمَرْأَةِ الثَّالِثَةَ بِسَهْمٍ فَوَضَعَهُ فِيهِ فَانْتَزَعَهُ فَوَضَعَهُ ثُمَّ رَكَعَ فَسَجَدَ ثُمَّ قَالَ لِصَاحِبِهِ اقْعُدْ فَقَدْ أُوتِيتُ قَالَ فَجَلَسَ ‏ ‏الْمُهَاجِرِيُّ فَلَمَّا رَآهُمَا صَاحِبُ الْمَرْأَةِ هَرَبَ وَعَرَفَ أَنَّهُ قَدْ ‏ ‏نُذِرَ ‏ ‏بِهِ قَالَ وَإِذَا الْأَنْصَارِيُّ يَمُوجُ دَمًا مِنْ رَمْيَاتِ صَاحِبِ الْمَرْأَةِ قَالَ فَقَالَ لَهُ أَخُوهُ ‏ ‏الْمُهَاجِرِيُّ يَغْفِرُ اللَّهُ لَكَ أَلَا كُنْتَ ‏ ‏آذَنْتَنِي ‏ ‏أَوَّلَ مَا رَمَاكَ قَالَ فَقَالَ كُنْتُ فِي سُورَةٍ مِنْ الْقُرْآنِ قَدْ افْتَتَحْتُهَا أُصَلِّي بِهَا فَكَرِهْتُ أَنْ أَقْطَعَهَا وَايْمُ اللَّهِ لَوْلَا أَنْ أُضَيِّعَ ‏ ‏ثَغْرًا ‏ ‏أَمَرَنِي بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِحِفْظِهِ لَقَطَعَ نَفْسِي قَبْلَ أَنْ أَقْطَعَهَا ‏","","",""],[14337,14337,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏وَاسِعِ بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ بِذَلِكَ مِنْ كُلِّ ‏ ‏جَادٍّ ‏ ‏عَشَرَةُ ‏ ‏أَوْسُقٍ ‏ ‏مِنْ التَّمْرِ ‏","","",""],[14338,14338,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏وَاسِعِ بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَمْرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ كُلِّ ‏ ‏جَادٍّ ‏ ‏بِعَشَرَةِ ‏ ‏أَوْسُقٍ ‏ ‏مِنْ تَمْرٍ ‏ ‏بِقِنْوٍ ‏ ‏يُعَلَّقُ فِي الْمَسْجِدِ لِلْمَسَاكِينِ ‏","","",""],[14339,14339,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏وَاسِعِ بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ أَذِنَ لِأَصْحَابِ ‏ ‏الْعَرَايَا ‏ ‏أَنْ يَبِيعُوهَا ‏ ‏بِخَرْصِهَا ‏ ‏يَقُولُ ‏ ‏الْوَسْقَ ‏ ‏وَالْوَسْقَيْنِ ‏ ‏وَالثَّلَاثَةَ وَالْأَرْبَعَةَ ‏","","",""],[14340,14340,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏دَاوُدُ بْنُ الْحُصَيْنِ ‏ ‏مَوْلَى ‏ ‏عَمْرِو بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏وَاقِدِ بْنِ عَمْرِو بْنِ سَعْدِ بْنِ مُعَاذٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا خَطَبَ أَحَدُكُمْ الْمَرْأَةَ فَقَدِرَ أَنْ يَرَى مِنْهَا بَعْضَ مَا يَدْعُوهُ إِلَيْهَا فَلْيَفْعَلْ ‏","","",""],[14341,14341,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏بَعْضِ أَهْلِهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏طَلْقِ بْنِ حَبِيبٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اتَّقُوا فَوْرَةَ الْعِشَاءِ كَأَنَّهُ لِمَا يُخَافُ مِنْ ‏ ‏الِاحْتِضَارِ ‏","","",""],[14342,14342,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَخِي بْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏وَقَدْ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏أخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى أَنَّهُ ‏ ‏مَنْ أَعْمَرَ رَجُلًا عُمْرَى لَهُ وَلِعَقِبِهِ فَإِنَّهَا لِلَّذِي يُعْمَرُهَا قَدْ بَتَّهَا مِنْ صَاحِبِهَا الَّذِي أَعْمَرَهَا مَا وَقَعَ مِنْ مَوَارِيثِ اللَّهِ وَحَقِّهِ ‏","","",""],[14343,14343,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏أَبَانُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدِ بْنِ جَبْرٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏نَهَانَا عَنْ أَنْ نَسْتَدْبِرَ الْقِبْلَةَ أَوْ نَسْتَقْبِلَهَا بِفُرُوجِنَا إِذَا ‏ ‏أَهْرَقْنَا ‏ ‏الْمَاءَ قَالَ ثُمَّ رَأَيْتُهُ قَبْلَ مَوْتِهِ بِعَامٍ يَبُولُ مُسْتَقْبِلَ الْقِبْلَةِ ‏","","",""],[14344,14344,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏مُعَاذُ بْنُ رِفَاعَةَ الْأَنْصَارِيُّ ثُمَّ الزُّرَقِيُّ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَمْرِو بْنِ الْجَمُوحِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا إِلَى ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏حِينَ تُوُفِّيَ قَالَ فَلَمَّا صَلَّى عَلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَوُضِعَ فِي قَبْرِهِ وَسُوِّيَ عَلَيْهِ ‏ ‏سَبَّحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَبَّحْنَا طَوِيلًا ثُمَّ كَبَّرَ فَكَبَّرْنَا فَقِيلَ يَا رَسُولَ اللَّهِ لِمَ سَبَّحْتَ ثُمَّ كَبَّرْتَ قَالَ لَقَدْ تَضَايَقَ عَلَى هَذَا الْعَبْدِ الصَّالِحِ قَبْرُهُ حَتَّى فَرَّجَهُ اللَّهُ عَزَّ وَجَلَّ عَنْهُ ‏","","",""],[14345,14345,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اسْتَكْثِرُوا مِنْ النِّعَالِ فَإِنَّ الرَّجُلَ لَا يَزَالُ رَاكِبًا مَا انْتَعَلَ ‏","","",""],[14346,14346,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ جَابِرٍ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْفَارُّ مِنْ الطَّاعُونِ كَالْفَارِّ مِنْ الزَّحْفِ وَالصَّابِرُ فِيهِ لَهُ أَجْرُ شَهِيدٍ ‏","","",""],[14347,14347,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏الْمُفَضَّلُ بْنُ فَضَالَةَ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏وَأَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْمُخَابَرَةِ ‏ ‏وَالْمُزَابَنَةِ ‏ ‏وَالْمُحَاقَلَةِ ‏ ‏وَبَيْعِ الثَّمَرِ حَتَّى ‏ ‏يُطْعَمَ ‏ ‏إِلَّا ‏ ‏الْعَرَايَا ‏","","",""],[14348,14348,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمُنْكَدِرُ بْنُ مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ مَعْرُوفٍ ‏ ‏صَدَقَةٌ ‏ ‏وَإِنَّ مِنْ الْمَعْرُوفِ أَنْ ‏ ‏تَلْقَى أَخَاكَ بِوَجْهٍ ‏ ‏طَلْقٍ ‏ ‏وَأَنْ تُفْرِغَ مِنْ دَلْوِكَ فِي إِنَاءِ أَخِيكَ ‏","","",""],[14349,14349,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏طَائِرُ كُلِّ إِنْسَانٍ فِي عُنُقِهِ ‏ ‏قَالَ ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏يَعْنِي الطِّيَرَةَ ‏","","",""],[14350,14350,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا أَحَدٌ يَدْعُو بِدُعَاءٍ إِلَّا آتَاهُ اللَّهُ مَا سَأَلَ أَوْ كَفَّ عَنْهُ مِنْ السُّوءِ مِثْلَهُ مَا لَمْ يَدْعُ بِإِثْمٍ أَوْ بِقَطِيعَةِ رَحِمٍ ‏","","",""],[14351,14351,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ غَزِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏قَدِمَ مِنْ ‏ ‏جَيْشَانَ ‏ ‏وَجَيْشَانُ ‏ ‏مِنْ ‏ ‏الْيَمَنِ ‏ ‏فَسَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ شَرَابٍ يَشْرَبُونَهُ بِأَرْضِهِمْ مِنْ الذُّرَةِ يُقَالُ لَهُ ‏ ‏الْمِزْرُ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمُسْكِرٌ هُوَ قَالَ نَعَمْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ مُسْكِرٍ حَرَامٌ وَإِنَّ عَلَى اللَّهِ عَزَّ وَجَلَّ عَهْدًا لِمَنْ يَشْرَبُ الْمُسْكِرَ أَنْ يَسْقِيَهُ مِنْ ‏ ‏طِينَةِ الْخَبَالِ ‏ ‏فَقَالُوا يَا رَسُولَ اللَّهِ وَمَا ‏ ‏طِينَةُ الْخَبَالِ ‏ ‏قَالَ عَرَقُ أَهْلِ النَّارِ ‏ ‏أَوْ عُصَارَةُ أَهْلِ النَّارِ ‏","","",""],[14352,14352,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ الْمَدِينِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَلِيِّ بْنِ رَبِيعَةَ السُّلَمِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏جَابِرُ ‏ ‏أَمَا عَلِمْتَ ‏ ‏أَنَّ اللَّهَ عَزَّ وَجَلَّ أَحْيَا أَبَاكَ فَقَالَ لَهُ تَمَنَّ عَلَيَّ فَقَالَ أُرَدُّ إِلَى الدُّنْيَا فَأُقْتَلُ مَرَّةً أُخْرَى فَقَالَ إِنِّي قَضَيْتُ الْحُكْمَ أَنَّهُمْ إِلَيْهَا لَا يُرْجَعُونَ ‏","","",""],[14353,14353,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْجَبَّارِ بْنُ مُحَمَّدٍ الْخَطَّابِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ يَعْنِي ابْنَ عَمْرٍو الرَّقِّيَّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عُمْرَةٌ فِي رَمَضَانَ تَعْدِلُ حَجَّةً ‏","","",""],[14354,14354,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْيَهُودِ ‏ ‏إِنِّي سَائِلُهُمْ عَنْ تُرْبَةِ الْجَنَّةِ وَهِيَ ‏ ‏دَرْمَكَةٌ ‏ ‏بَيْضَاءُ فَسَأَلَهُمْ فَقَالُوا هِيَ خُبْزَةٌ يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْخُبْزَةُ مِنْ ‏ ‏الدَّرْمَكِ ‏","","",""],[14355,14355,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مِينَاءَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ الثَّمَرَةِ حَتَّى ‏ ‏تُشْقَحَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِسَعِيدٍ ‏ ‏مَا ‏ ‏تُشْقَحُ ‏ ‏قَالَ ‏ ‏تَحْمَارُّ ‏ ‏وَتَصْفَارُّ ‏ ‏وَيُؤْكَلُ مِنْهَا ‏","","",""],[14356,14356,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَحُمَيْدٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ ‏ ‏يُتَعَاطَى السَّيْفُ ‏ ‏مَسْلُولًا ‏","","",""],[14357,14357,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏حَدَّثَنِي ‏ ‏جَابِرُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعُمْرَى ‏ ‏جَائِزَةٌ ‏","","",""],[14358,14358,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ مِينَاءَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلِي وَمَثَلُ الْأَنْبِيَاءِ كَمَثَلِ رَجُلٍ أَوْقَدَ نَارًا فَجَعَلَ الْفَرَاشُ ‏ ‏وَالْجَنَادِبُ ‏ ‏يَقَعْنَ فِيهَا قَالَ وَهُوَ يَذُبُّهُنَّ عَنْهَا قَالَ وَأَنَا آخِذٌ بِحُجَزِكُمْ عَنْ النَّارِ وَأَنْتُمْ ‏ ‏تَفَلَّتُونَ مِنْ يَدِي ‏","","",""],[14359,14359,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مِينَاءَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلِي وَمَثَلُ الْأَنْبِيَاءِ كَمَثَلِ رَجُلٍ ابْتَنَى دَارًا فَأَكْمَلَهَا وَأَحْسَنَهَا إِلَّا مَوْضِعَ لَبِنَةٍ فَجَعَلَ النَّاسُ يَدْخُلُونَهَا وَيَعْجَبُونَ وَيَقُولُونَ لَوْلَا مَوْضِعُ اللَّبِنَةِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَنَا مَوْضِعُ اللَّبِنَةِ جِئْتُ فَخَتَمْتُ الْأَنْبِيَاءَ ‏","","",""],[14360,14360,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مِينَاءَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى عَلَى ‏ ‏أَصْحَمَةَ النَّجَاشِيِّ ‏ ‏فَكَبَّرَ عَلَيْهِ أَرْبَعًا ‏","","",""],[14361,14361,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏عَنْ لُحُومِ الْحُمُرِ وَأَذِنَ فِي لُحُومِ الْخَيْلِ ‏","","",""],[14362,14362,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْثَرُ بْنُ الْقَاسِمِ أَبُو زُبَيْدٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏أَهْدَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏الْبَيْتِ ‏ ‏غَنَمًا ‏","","",""],[14363,14363,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏الْمُفَضَّلُ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ حَرْمَلَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ الْحُصَيْنِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبْدِ الرَّحْمَنِ بْنِ جَرْهَدٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَجُلًا يَقُولُ ‏ ‏لِجَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏مَنْ بَقِيَ مَعَكَ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ بَقِيَ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏وَسَلَمَةُ بْنُ الْأَكْوَعِ ‏ ‏فَقَالَ رَجُلٌ أَمَّا ‏ ‏سَلَمَةُ ‏ ‏فَقَدْ ارْتَدَّ عَنْ هِجْرَتِهِ فَقَالَ ‏ ‏جَابِرٌ ‏ ‏لَا تَقُلْ ذَلِكَ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لِأَسْلَمَ ‏ ‏ابْدُوا يَا ‏ ‏أَسْلَمُ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ وَإِنَّا ‏ ‏نَخَافُ أَنْ نَرْتَدَّ بَعْدَ هِجْرَتِنَا فَقَالَ إِنَّكُمْ أَنْتُمْ تُهَاجِرُونَ حَيْثُ كُنْتُمْ ‏","","",""],[14364,14364,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏الْمُطَّلِبِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏شَهِدْتُ الْأَضْحَى مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْمُصَلَّى فَلَمَّا قَضَى خُطْبَتَهُ أَتَى بِكَبْشٍ فَذَبَحَهُ بِيَدِهِ وَقَالَ ‏ ‏بِسْمِ اللَّهِ وَبِاللَّهِ اللَّهُمَّ إِنَّ هَذَا عَنِّي وَعَمَّنْ لَمْ يُضَحِّ مِنْ أُمَّتِي ‏","","",""],[14365,14365,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏وَقُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏الْمُطَّلِبِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏قُتَيْبَةُ ‏ ‏فِي حَدِيثِهِ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏صَيْدُ الْبَرِّ لَكُمْ حَلَالٌ ‏ ‏قَالَ ‏ ‏سَعِيدٌ ‏ ‏وَأَنْتُمْ حُرُمٌ مَا لَمْ تَصِيدُوهُ أَوْ يُصَدْ لَكُمْ ‏","","",""],[14366,14366,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏الْمُطَّلِبِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏شَهِدْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْأَضْحَى بِالْمُصَلَّى فَلَمَّا قَضَى خُطْبَتَهُ نَزَلَ مِنْ مِنْبَرِهِ وَأَتَى بِكَبْشٍ فَذَبَحَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِهِ وَقَالَ ‏ ‏بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ هَذَا عَنِّي وَعَمَّنْ لَمْ يُضَحِّ مِنْ أُمَّتِي ‏","","",""],[14367,14367,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزَاةٍ قَالَ فَاسْتَأْذَنْتُ أَتَعَجَّلُ قُلْتُ إِنِّي تَزَوَّجْتُ قَالَ ‏ ‏ثَيِّبًا ‏ ‏أَمْ ‏ ‏بِكْرًا ‏ ‏قَالَ قُلْتُ ‏ ‏ثَيِّبًا ‏ ‏قَالَ ‏ ‏فَأَلَّا كَانَتْ ‏ ‏بِكْرًا ‏ ‏تُلَاعِبُهَا وَتُلَاعِبُكَ قَالَ انْطَلِقْ وَاعْمَلْ عَمَلًا كَيِّسًا ‏ ‏قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَعْنِي لَا ‏ ‏تَطْرُقْهُنَّ ‏ ‏لَيْلًا ‏","","",""],[14368,14368,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَمْشِيَ أَحَدُنَا فِي النَّعْلِ الْوَاحِدَةِ ‏","","",""],[14369,14369,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَبِيبٌ الْمُعَلِّمُ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏احْبِسُوا صِبْيَانَكُمْ حَتَّى تَذْهَبَ ‏ ‏فَوْرَةُ ‏ ‏الْعِشَاءِ فَإِنَّهَا سَاعَةٌ تَخْتَرِقُ فِيهَا الشَّيَاطِينُ ‏","","",""],[14370,14370,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نُغْلِقَ الْأَبْوَابَ وَأَنْ ‏ ‏نُوكِئَ ‏ ‏الْأَسْقِيَةَ ‏ ‏وَأَنْ نُطْفِئَ الْمَصَابِيحَ وَأَنْ نَكُفَّ ‏ ‏فَوَاشِيَنَا ‏ ‏حَتَّى تَذْهَبَ ‏ ‏فَحْمَةُ ‏ ‏الْعِشَاءِ وَنَهَانَا أَنْ يَأْكُلَ الرَّجُلُ بِشِمَالِهِ وَأَنْ يَمْشِيَ فِي النَّعْلِ الْوَاحِدَةِ وَعَنْ ‏ ‏الصَّمَّاءِ ‏ ‏وَالِاحْتِبَاءِ ‏ ‏فِي ثَوْبٍ وَاحِدٍ ‏","","",""],[14371,14371,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَيْسُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَرْبَعٍ ‏ ‏خَلَوْنَ ‏ ‏مِنْ ذِي الْحِجَّةِ فَلَمَّا طُفْنَا ‏ ‏بِالْبَيْتِ ‏ ‏وَبَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اجْعَلُوهَا عُمْرَةً إِلَّا مَنْ كَانَ مَعَهُ ‏ ‏الْهَدْيُ ‏ ‏فَلَمَّا كَانَ ‏ ‏يَوْمُ التَّرْوِيَةِ ‏ ‏أَهَلُّوا ‏ ‏بِالْحَجِّ فَلَمَّا كَانَ ‏ ‏يَوْمُ النَّحْرِ ‏ ‏طَافُوا وَلَمْ يَطُوفُوا بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏","","",""],[14372,14372,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏و عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَدِّدُوا وَقَارِبُوا وَلَنْ يُنْجِيَ أَحَدًا مِنْكُمْ عَمَلُهُ قُلْنَا وَلَا أَنْتَ يَا رَسُولَ اللَّهِ قَالَ وَلَا أَنَا إِلَّا أَنْ ‏ ‏يَتَغَمَّدَنِي ‏ ‏اللَّهُ مِنْهُ بِرَحْمَةٍ ‏","","",""],[14373,14373,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏ذَبَحْنَا يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏الْخَيْلَ وَالْبِغَالَ وَالْحَمِيرَ فَنَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْبِغَالِ وَالْحَمِيرِ وَلَمْ يَنْهَ عَنْ الْخَيْلِ ‏","","",""],[14374,14374,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ ‏ ‏بِجَابِرٍ ‏ ‏فِي غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏قَالَ وَقَدْ أَعْيَا بَعِيرِي فَقَالَ مَا شَأْنُكَ يَا ‏ ‏جَابِرُ ‏ ‏فَقُلْتُ بَعِيرِي قَدْ ‏ ‏رَزَمَ ‏ ‏قَالَ فَأَتَاهُ مِنْ قِبَلِ ‏ ‏عَجُزِهِ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏وَعَجُزُهُ سَوَاءٌ ‏ ‏فَدَعَا ‏ ‏وَزَجَرَهُ ‏ ‏قَالَ فَلَمْ يَزَلْ يَقْدُمُ الْإِبِلَ قَالَ فَأَتَى عَلَيْهِ فَقَالَ مَا فَعَلَ الْبَعِيرُ قُلْتُ مَا زَالَ يَقْدُمُهَا قَالَ بِكَمْ أَخَذْتَهُ فَقُلْتُ بِثَلَاثَةَ عَشَرَ دِينَارًا قَالَ ‏ ‏فَبِعْنِي بِالثَّمَنِ وَلَكَ ظَهْرُهُ إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏قُلْتُ نَعَمْ قَالَ فَلَمَّا قَدِمْتُ ‏ ‏الْمَدِينَةَ ‏ ‏خَطَمْتُهُ ‏ ‏ثُمَّ أَتَيْتُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَعْطَانِي الثَّمَنَ وَأَعْطَانِي الْبَعِيرَ ‏","","",""],[14375,14375,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ يَوْمَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏وَعَلَيْهِ عِمَامَةٌ سَوْدَاءُ ‏","","",""],[14376,14376,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَوَى ‏ ‏سَعْدَ بْنَ مُعَاذٍ ‏ ‏مِنْ رَمْيَتِهِ ‏","","",""],[14377,14377,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏رَجُلٌ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَخْطُبُ فَقَالَ ‏ ‏أَصَلَّيْتَ الرَّكْعَتَيْنِ فَقَالَ لَا قَالَ فَصَلِّهِمَا ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏جَابِرٌ ‏ ‏يَقُولُ ‏ ‏إِنْ صَلَّى فِي بَيْتِهِ يُعْجِبُهُ إِذَا دَخَلَ أَنْ يُصَلِّيَهُمَا ‏","","",""],[14378,14378,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَهُ لِبَعْضِ حَاجَتِهِ قَالَ فَجَاءَ وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى رَاحِلَتِهِ قَالَ فَسَلَّمَ عَلَيْهِ فَسَكَتَ فَسَلَّمَ عَلَيْهِ فَسَكَتَ فَسَلَّمَ عَلَيْهِ فَسَكَتَ ثَلَاثَ مَرَّاتٍ قَالَ فَقَالَ لَهُ لَمَّا فَرَغَ ‏ ‏إِنَّهُ لَمْ يَمْنَعْنِي أَنْ أَرُدَّ عَلَيْكَ إِلَّا أَنِّي كُنْتُ أُصَلِّي قَالَ فَصَلَّى حَيْثُ تَوَجَّهَتْ بِهِ رَاحِلَتُهُ ‏","","",""],[14379,14379,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْتَجَمَ ‏ ‏وَهُوَ مُحْرِمٌ مِنْ ‏ ‏وَثْيٍ ‏ ‏كَانَ بِهِ ‏","","",""],[14380,14380,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَقَقْتُ الْبَابَ فَقَالَ ‏ ‏مَنْ هَذَا قُلْتُ أَنَا قَالَ أَنَا أَنَا كَأَنَّهُ كَرِهَهُ ‏","","",""],[14381,14381,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مِينَاءَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى عَلَى ‏ ‏أَصْحَمَةَ النَّجَاشِيِّ ‏ ‏فَكَبَّرَ عَلَيْهِ أَرْبَعًا ‏","","",""],[14382,14382,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏مَطَرٌ ‏ ‏عَنْ ‏ ‏رَجُلٍ أَحْسَبُهُ ‏ ‏الْحَسَنَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏أُعْفِي مَنْ قَتَلَ بَعْدَ أَخْذِهِ ‏ ‏الدِّيَةَ ‏","","",""],[14383,14383,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ يَزِيدَ ‏ ‏أَخْبَرَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَحْيَا أَرْضًا دَعْوَةً مِنْ الْمَصْرِ ‏ ‏أَوْ ‏ ‏رَمْيَةً ‏ ‏مِنْ الْمَصْرِ ‏ ‏فَهِيَ لَهُ ‏","","",""],[14384,14384,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْرُجُ فِي ‏ ‏الْعِيدِ ‏ ‏وَيُخْرِجُ أَهْلَهُ ‏","","",""],[14385,14385,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَيْسُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحَرَ الْبَدَنَةَ عَنْ سَبْعَةٍ وَالْبَقَرَةَ عَنْ سَبْعَةٍ ‏","","",""],[14386,14386,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏مُحَارِبُ بْنُ دِثَارٍ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏جَابِرًا ‏ ‏يَقُولُ ‏ ‏إِنَّهُ كَانَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ ‏ ‏فَلَمَّا أَتَى ‏ ‏الْمَدِينَةَ ‏ ‏أَمَرَهُ أَنْ يَأْتِيَ الْمَسْجِدَ فَيُصَلِّيَ رَكْعَتَيْنِ ‏","","",""],[14387,14387,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏وَعَاصِمٌ الْأَحْوَلُ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏تَمَتَّعْنَا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُتْعَتَيْنِ الْحَجَّ وَالنِّسَاءَ ‏ ‏وَقَدْ قَالَ ‏ ‏حَمَّادٌ ‏ ‏أَيْضًا مُتْعَةَ الْحَجِّ وَمُتْعَةَ النِّسَاءِ ‏ ‏فَلَمَّا كَانَ ‏ ‏عُمَرُ ‏ ‏نَهَانَا عَنْهُمَا فَانْتَهَيْنَا ‏","","",""],[14388,14388,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ سَأَلَ ‏ ‏سُلَيْمَانُ بْنُ مُوسَى ‏ ‏عَطَاءً ‏ ‏وَأَنَا شَاهِدٌ ‏ ‏قَالَ حَدَّثَكَ ‏ ‏جَابِرٌ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يُنْبَذَ الْبُسْرُ وَالتَّمْرُ جَمِيعًا وَالزَّبِيبُ وَالتَّمْرُ جَمِيعًا قَالَ ‏ ‏عَطَاءٌ ‏ ‏نَعَمْ ‏","","",""],[14389,14389,"","","‏ ‏و قَالَ ‏ ‏لَهُ ‏ ‏سُلَيْمَانُ بْنُ مُوسَى ‏ ‏وَأَنَا شَاهِدٌ ‏ ‏حَدَّثَكَ ‏ ‏جَابِرٌ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَانَتْ لَهُ أَرْضٌ فَلْيَزْرَعْهَا ‏ ‏أَوْ لِيُزْرِعْهَا ‏ ‏أَخَاهُ وَلَا ‏ ‏يُكْرِيهَا قَالَ ‏ ‏عَطَاءٌ ‏ ‏نَعَمْ ‏","","",""],[14390,14390,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏حَبِيبٌ الْمُعَلِّمُ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَجُلًا قَالَ يَوْمَ الْفَتْحِ يَا رَسُولَ اللَّهِ ‏ ‏إِنِّي نَذَرْتُ إِنْ فَتَحَ اللَّهُ عَلَيْكَ ‏ ‏مَكَّةَ ‏ ‏أَنْ أُصَلِّيَ فِي ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏فَقَالَ صَلِّ هَاهُنَا فَسَأَلَهُ فَقَالَ صَلِّ هَاهُنَا فَسَأَلَهُ فَقَالَ شَأْنَكَ إِذًا ‏","","",""],[14391,14391,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏قَالَ قَالَ ‏ ‏لِي ‏ ‏سُلَيْمَانُ بْنُ هِشَامٍ ‏ ‏إِنَّ هَذَا ‏ ‏يَعْنِي ‏ ‏الزُّهْرِيَّ ‏ ‏لَا يَدَعُنَا نَأْكُلُ شَيْئًا إِلَّا أَمَرَنَا أَنْ نَتَوَضَّأَ مِنْهُ ‏ ‏يَعْنِي مَا مَسَّتْهُ النَّارُ ‏ ‏قَالَ فَقُلْتُ لَهُ ‏ ‏سَأَلْتُ عَنْهُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏فَقَالَ ‏ ‏إِذَا أَكَلْتَهُ فَهُوَ طَيِّبٌ لَيْسَ عَلَيْكَ فِيهِ وُضُوءٌ فَإِذَا خَرَجَ فَهُوَ خَبِيثٌ عَلَيْكَ فِيهِ الْوُضُوءُ ‏ ‏قَالَ فَهَلْ بِالْبَلَدِ أَحَدٌ قَالَ قُلْتُ نَعَمْ أَقْدَمُ رَجُلٍ فِي جَزِيرَةِ ‏ ‏الْعَرَبِ ‏ ‏عِلْمًا قَالَ مَنْ قُلْتُ ‏ ‏عَطَاءُ بْنُ أَبِي رَبَاحٍ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فَأَرْسَلَ إِلَيْهِ فَجِيءَ بِهِ ‏ ‏قَالَ فَبَعَثَ إِلَيْهِ فَقَالَ ‏ ‏حَدَّثَنِي ‏ ‏جَابِرٌ ‏ ‏أَنَّهُمْ ‏ ‏أَكَلُوا مَعَ ‏ ‏أَبِي بَكْرٍ الصِّدِّيقِ ‏ ‏خُبْزًا وَلَحْمًا فَصَلَّى وَلَمْ يَتَوَضَّأْ ‏","","",""],[14392,14392,"","","‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏لِعَطَاءٍ ‏ ‏مَا تَقُولُ ‏ ‏يَعْنِي فِي الْعُمْرَى قَالَ حَدَّثَنِي ‏ ‏جَابِرٌ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعُمْرَى جَائِزَةٌ ‏","","",""],[14393,14393,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏وَسَعِيدِ بْنِ مِينَا ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْمُحَاقَلَةِ ‏ ‏وَالْمُزَابَنَةِ ‏ ‏وَالْمُعَاوَمَةِ ‏ ‏فَقَالَ أَحَدُهُمَا ‏ ‏وَبَيْعِ السِّنِينَ ‏ ‏وَعَنْ بَيْعِ ‏ ‏الثُّنْيَا ‏ ‏وَرَخَّصَ فِي ‏ ‏الْعَرَايَا ‏","","",""],[14394,14394,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ مِهْرَانَ الْأَعْمَشُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سُفْيَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ أَهْلَ الْجَنَّةِ يَأْكُلُونَ فِيهَا وَيَشْرَبُونَ لَا يَبُولُونَ وَلَا ‏ ‏يَتَغَوَّطُونَ ‏ ‏وَلَا يَتْفُلُونَ وَلَا يَمْتَخِطُونَ طَعَامُهُمْ ‏ ‏جُشَاءٌ ‏ ‏وَرَشْحٌ ‏ ‏كَرَشْحِ ‏ ‏الْمِسْكِ ‏","","",""],[14395,14395,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُهِلِّينَ ‏ ‏بِالْحَجِّ فَطُفْنَا ‏ ‏بِالْبَيْتِ ‏ ‏وَسَعَيْنَا بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏فَأَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نَحِلَّ قَالَ فَخَرَجْنَا إِلَى ‏ ‏الْبَطْحَاءِ ‏ ‏قَالَ فَجَعَلَ الرَّجُلُ يَقُولُ عَهْدِي بِأَهْلِي ‏ ‏الْيَوْمَ فَقَالَ النَّاسُ فِي ذَلِكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ اسْتَقْبَلْتُ مِنْ أَمْرِي مَا اسْتَدْبَرْتُ مِنْهُ لَأَحْلَلْتُ وَلَمْ يَحِلَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَنَّهُ سَاقَ الْهَدْيَ فَأَحْرَمْنَا حِينَ تَوَجَّهْنَا إِلَى ‏ ‏مِنًى ‏","","",""],[14396,14396,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏نَحَرْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏سَبْعِينَ بَدَنَةً الْبَدَنَةُ عَنْ سَبْعَةٍ ‏","","",""],[14397,14397,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَلَبَ وَسَأَلَ أَهْلَهُ ‏ ‏الْأُدْمَ ‏ ‏قَالُوا مَا عِنْدَنَا إِلَّا خَلٌّ قَالَ فَدَعَا بِهِ فَجَعَلَ يَأْكُلُ بِهِ وَيَقُولُ ‏ ‏نِعْمَ ‏ ‏الْأُدْمُ ‏ ‏الْخَلُّ ‏","","",""],[14398,14398,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّهُمْ كَانُوا لَا يَضَعُونَ أَيْدِيَهُمْ فِي الطَّعَامِ حَتَّى يَكُونَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ يَبْدَأُ ‏","","",""],[14399,14399,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَجُلًا ذَبَحَ قَبْلَ أَنْ يُصَلِّيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَتُودًا ‏ ‏جَذَعًا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُجْزِئُ عَنْ أَحَدٍ بَعْدَكَ وَنَهَى أَنْ يَذْبَحُوا حَتَّى يُصَلُّوا ‏","","",""],[14400,14400,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَقْبَلْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى إِذَا كُنَّا ‏ ‏بِذَاتِ الرِّقَاعِ ‏ ‏قَالَ كُنَّا إِذَا أَتَيْنَا عَلَى شَجَرَةٍ ظَلِيلَةٍ تَرَكْنَاهَا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ ‏ ‏رَجُلٌ ‏ ‏مِنْ الْمُشْرِكِينَ وَسَيْفُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُعَلَّقٌ بِشَجَرَةٍ فَأَخَذَ سَيْفَ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاخْتَرَطَهُ ‏ ‏ثُمَّ قَالَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَخَافُنِي قَالَ لَا قَالَ فَمَنْ يَمْنَعُكَ مِنِّي قَالَ اللَّهُ عَزَّ وَجَلَّ يَمْنَعُنِي مِنْكَ قَالَ فَتَهَدَّدَهُ ‏ ‏أَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَغْمَدَ ‏ ‏السَّيْفَ وَعَلَّقَهُ ‏ ‏فَنُودِيَ بِالصَّلَاةِ فَصَلَّى بِطَائِفَةٍ رَكْعَتَيْنِ وَتَأَخَّرُوا وَصَلَّى بِالطَّائِفَةِ الْأُخْرَى رَكْعَتَيْنِ فَكَانَتْ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَعُ رَكَعَاتٍ وَلِلْقَوْمِ رَكْعَتَانِ ‏","","",""]];
